import '../models/guide.dart';

const List<GuideStep> _emeraldContinuationSteps = [
  GuideStep(section: 'Dewford Town i druga odznaka', title: 'Odzyskaj Devon Goods i uratuj Peeko', description: 'Na Route 116 wejdź do Rusturf Tunnel. Pokonaj członka Team Aqua, odzyskaj Devon Goods i uratuj Wingulla Peeko należącego do Mr. Brineya.', location: 'Route 116 / Rusturf Tunnel', pokemon: ['Poochyena', 'Whismur'], encounterRatesPercent: {'Poochyena': 28, 'Nincada': 20, 'Taillow': 20, 'Whismur': 20, 'Abra': 10, 'Skitty': 2}, items: ['Devon Goods', 'Peeko']),
  GuideStep(section: 'Dewford Town i druga odznaka', title: 'Odbierz PokéNav i list do Stevena', description: 'Oddaj Devon Goods w Devon Corporation. Mr. Stone przekaże ci PokéNav oraz list dla Stevena, który przebywa w Granite Cave.', location: 'Rustboro City', items: ['PokéNav', 'Letter']),
  GuideStep(section: 'Dewford Town i druga odznaka', title: 'Przepłyń do Dewford Town', description: 'Wróć do domku Mr. Brineya na Route 104. Po uratowaniu Peeko przewiezie cię łodzią do Dewford Town.', location: 'Route 104 / Dewford Town'),
  GuideStep(section: 'Dewford Town i druga odznaka', title: 'Pokonaj Brawly’ego', description: 'Brawly specjalizuje się w typie Fighting. Wykorzystaj ataki Flying lub Psychic. Po zwycięstwie otrzymasz Knuckle Badge i TM08 Bulk Up.', location: 'Dewford Gym', pokemon: ['Machop', 'Meditite', 'Makuhita'], items: ['Knuckle Badge', 'TM08 Bulk Up']),
  GuideStep(section: 'Dewford Town i druga odznaka', title: 'Zbadaj pierwsze piętro Granite Cave', description: 'Na 1F możesz spotkać Zubata, Makuhitę, Abrę i Geodude. Procenty pokazują udział gatunku w zwykłych spotkaniach podczas chodzenia; nie łącz ich z Rock Smash na niższym piętrze.', location: 'Granite Cave — 1F', pokemon: ['Zubat', 'Makuhita', 'Abra', 'Geodude'], encounterRatesPercent: {'Zubat': 30, 'Makuhita': 50, 'Abra': 10, 'Geodude': 10}),
  GuideStep(section: 'Dewford Town i druga odznaka', title: 'Zbadaj dolny poziom Granite Cave — B1F', description: 'Na B1F pojawiają się Aron i Sableye obok Zubata, Makuhity i Abry. Sableye jest szczególnie przydatny do uzupełnienia regionalnego Pokédexu.', location: 'Granite Cave — B1F', pokemon: ['Zubat', 'Aron', 'Abra', 'Sableye', 'Makuhita'], encounterRatesPercent: {'Zubat': 30, 'Aron': 40, 'Abra': 10, 'Sableye': 10, 'Makuhita': 10}),
  GuideStep(section: 'Dewford Town i druga odznaka', title: 'Zbadaj najniższy poziom Granite Cave — B2F', description: 'Na B2F nadal spotkasz Zubata, Arona, Abrę i Sableye. Procenty dotyczą zwykłych spotkań podczas chodzenia po jaskini.', location: 'Granite Cave — B2F', pokemon: ['Zubat', 'Aron', 'Abra', 'Sableye'], encounterRatesPercent: {'Zubat': 30, 'Aron': 40, 'Abra': 10, 'Sableye': 20}),
  GuideStep(section: 'Dewford Town i druga odznaka', title: 'Użyj Rock Smash w Granite Cave', description: 'Na B2F rozbijaj skały. W spotkaniach wywołanych przez Rock Smash Geodude stanowi 70% puli, a Nosepass 30%. To osobna metoda, dlatego nie mieszaj tych wartości z procentami spotkań podczas chodzenia.', location: 'Granite Cave — B2F / Rock Smash', pokemon: ['Geodude', 'Nosepass'], encounterRatesPercent: {'Geodude': 70, 'Nosepass': 30}, items: ['Rock Smash']),
  GuideStep(section: 'Dewford Town i druga odznaka', title: 'Pokonaj trenerów na Route 105', description: 'Na trasie jest 7 trenerów. Foster (Ruin Maniac): Sandshrew i Sandslash, oba Lv.25, z Dig, Slash, Sand Attack i Poison Sting. Luis: Carvanha Lv.26 (Rage, Focus Energy, Scary Face, Crunch). Dominik: Tentacool Lv.26 (Supersonic, Constrict, Acid, Bubble Beam). Beverly: Wingull i Wailmer Lv.25. Imani: Marill Lv.26. Josue: Taillow i Wingull Lv.25. Andres: dwa Sandshrew Lv.25. To lista pierwszych walk, nie późniejszych rewanżów.', location: 'Route 105', pokemon: ['Sandshrew', 'Sandslash', 'Carvanha', 'Tentacool', 'Wingull', 'Wailmer', 'Marill', 'Taillow']),
  GuideStep(section: 'Dewford Town i druga odznaka', title: 'Pokonaj trenerów na Route 106', description: 'Na trasie są 4 walki. Douglas ma dwa Tentacool Lv.24 (Poison Sting, Supersonic, Constrict, Acid). Kyla używa Wailmera Lv.26 (Water Gun, Rollout, Whirlpool, Astonish). Elliot ma Magikarp Lv.10, Tentacool Lv.7 i Magikarp Lv.10; Ned ma Tentacool Lv.11. To pierwsze składy — późniejsze rewanże przez Vs. Seeker są mocniejsze.', location: 'Route 106', pokemon: ['Tentacool', 'Wailmer', 'Magikarp']),
  GuideStep(section: 'Dewford Town i druga odznaka', title: 'Pokonaj trenerów na Route 107', description: 'Na trasie jest 6 trenerów. Darrin: Tentacool, Wingull i Tentacool Lv.24. Tony: Carvanha Lv.26 (Rage, Focus Energy, Scary Face, Crunch). Denise: Wingull i Goldeen Lv.25. Beth: Goldeen Lv.26. Lisa i Ray walczą w Double Battle z Goldeen Lv.27 i Tentacool Lv.25. Camron używa Staryu Lv.26.', location: 'Route 107', pokemon: ['Tentacool', 'Wingull', 'Carvanha', 'Goldeen', 'Staryu']),
  GuideStep(section: 'Dewford Town i druga odznaka', title: 'Pokonaj trenerów na Route 108', description: 'Na trasie jest 6 trenerów. Jerome: Tentacruel Lv.26. Matthew: Carvanha Lv.26. Tara: Horsea i Marill Lv.25. Missy: Goldeen Lv.26. Carolina (Cooltrainer): Manectric i Swellow Lv.24. Cory (Sailor): Wingull, Machop i Tentacool Lv.24. Opis dotyczy pierwszych walk, bez rematchy Vs. Seeker.', location: 'Route 108', pokemon: ['Tentacruel', 'Carvanha', 'Horsea', 'Marill', 'Goldeen', 'Manectric', 'Swellow', 'Wingull', 'Machop', 'Tentacool']),
  GuideStep(section: 'Dewford Town i druga odznaka', title: 'Dostarcz list Stevenowi', description: 'Wejdź do Granite Cave. W ciemniejszych częściach jaskini przyda się Flash. Znajdź Stevena i przekaż mu Letter; w nagrodę otrzymasz TM47 Steel Wing.', location: 'Granite Cave', items: ['HM05 Flash', 'TM47 Steel Wing']),
  GuideStep(section: 'Slateport i trzecia odznaka', title: 'Dotrzyj do Slateport City', description: 'Mr. Briney może przewieźć cię na Route 109. Przejdź przez plażę do Slateport City, zbierając przedmioty i walcząc z trenerami.', location: 'Route 109 / Slateport City'),
  GuideStep(section: 'Slateport i trzecia odznaka', title: 'Pokonaj trenerów na Route 109', description: 'Wróć na plażę i oczyść ją z trenerów. Tuber Austina i Tuber Gwen używają Marill Lv.26. Swimmer David: Tentacool i Carvanha Lv.25. Swimmer Alice: Goldeen, Wingull i Goldeen Lv.24. Fisherman Carter: Wailmer i Tentacruel Lv.25. Bird Keeper Elijah: dwa Skarmory Lv.25. Young Couple Mel & Paul: Dustox i Beautifly Lv.27 (Double Battle). Carter i Elijah mogą walczyć razem. Zbierz ukryty Heart Scale na wysepce pary oraz PP Up na wschodniej łasze.', location: 'Route 109', pokemon: ['Marill', 'Tentacool', 'Carvanha', 'Goldeen', 'Wingull', 'Wailmer', 'Tentacruel', 'Skarmory', 'Dustox', 'Beautifly'], items: ['Heart Scale', 'PP Up']),
  GuideStep(section: 'Slateport i trzecia odznaka', title: 'Oczyść Oceanic Museum z Team Aqua', description: 'Odwiedź Oceanic Museum i pokonaj członków Team Aqua, którzy próbują przejąć urządzenia badawcze. Po wydarzeniu rusz na północ Route 110.', location: 'Oceanic Museum'),
  GuideStep(section: 'Slateport i trzecia odznaka', title: 'Pokonaj rywala na Route 110', description: 'Na Route 110 spotkasz rywala. Jego drużyna zależy od wybranego startera; przygotuj się na Slugmę, Wingulla lub Lombre oraz rozwiniętego startera na poziomie 20.', location: 'Route 110', pokemon: ['Slugma', 'Wingull', 'Lombre', 'Grovyle', 'Combusken', 'Marshtomp']),
  GuideStep(section: 'Slateport i trzecia odznaka', title: 'Pokonaj trenerów i zbierz przedmioty na Route 110', description: 'Przed przejściem do Mauville pokonaj trenerów na trasie. Pokéfan Isabel i Kaleb mają Plusle oraz Minun Lv.14 (Oran Berry). Youngster Timmy: Aron Lv.15 i Electrike Lv.13. Collector Edwin: Lombre i Nuzleaf Lv.14. Guitarist Joseph: Electrike i Voltorb Lv.14. Psychic Edward: Abra Lv.15. Triathlete Alyssa: Magnemite Lv.15. Fisherman Dale: Tentacool Lv.11 i Wailmer Lv.14, powtarzający się skład. Zbierz Dire Hit, Full Heal (ukryty), Itemfinder od rywala, Great Ball i Revive (ukryte), Elixir, ukryty Poké Ball oraz Nanab Berries. Spotkania w trawie: Electrike 30%, Poochyena 20%, Minun 15%, Gulpin 15%, Oddish 10%, Wingull 8%, Plusle 2%.', location: 'Route 110', pokemon: ['Plusle', 'Minun', 'Aron', 'Electrike', 'Lombre', 'Nuzleaf', 'Voltorb', 'Abra', 'Magnemite', 'Tentacool', 'Wailmer', 'Poochyena', 'Gulpin', 'Oddish', 'Wingull'], encounterRatesPercent: {'Electrike': 30, 'Poochyena': 20, 'Minun': 15, 'Gulpin': 15, 'Oddish': 10, 'Wingull': 8, 'Plusle': 2}, items: ['Dire Hit', 'Full Heal', 'Itemfinder', 'Great Ball', 'Revive', 'Elixir', 'Poké Ball', 'Nanab Berry']),
  GuideStep(section: 'Slateport i trzecia odznaka', title: 'Odbierz Rock Smash i rower', description: 'W Mauville City odwiedź Rydel’s Cycles i wybierz Mach Bike lub Acro Bike. Odbierz HM06 Rock Smash w jednym z domów.', location: 'Mauville City', items: ['HM06 Rock Smash', 'Mach Bike lub Acro Bike']),
  GuideStep(section: 'Slateport i trzecia odznaka', title: 'Pokonaj Wattsona', description: 'Wattson używa Pokémonów typu Electric. Najlepiej sprawdzają się ruchy Ground. Po zwycięstwie otrzymasz Dynamo Badge i TM34 Shock Wave.', location: 'Mauville Gym', pokemon: ['Voltorb', 'Electrike', 'Magneton', 'Manectric'], items: ['Dynamo Badge', 'TM34 Shock Wave']),
  GuideStep(section: 'Mauville i Route 117', title: 'Pokonaj trenerów i zbierz przedmioty na Route 117', description: 'Na trasie czeka 9 pierwszych walk: Triathlete Dylan — Doduo Lv.17; Sr. and Jr. Anna & Meg — Zigzagoon Lv.15 i Makuhita Lv.17; Pokémon Breeder Isaac — sześć Pokémonów Lv.11 (Whismur, Zigzagoon, Aron, Poochyena, Taillow, Makuhita); Triathlete Maria — Doduo Lv.17; Bug Maniac Derek — Dustox i Beautifly Lv.16; Psychic Brandi — Ralts Lv.17; Triathlete Melina — Doduo Lv.17; Battle Girl Aisha — Meditite Lv.17; Pokémon Breeder Lydia — sześć Pokémonów Lv.11 (Wingull, Shroomish, Marill, Roselia, Skitty, Goldeen). Brandi, Melina i Aisha mogą uruchomić walkę podwójną. Spotkania w trawie: Oddish 40%, Poochyena 30%, Illumise 18%, Marill 10%, Seedot 1%, Volbeat 1%. Zbierz Wepear Berries, Revive, Great Ball i ukryty Repel.', location: 'Route 117', pokemon: ['Doduo', 'Zigzagoon', 'Makuhita', 'Whismur', 'Aron', 'Poochyena', 'Taillow', 'Dustox', 'Beautifly', 'Ralts', 'Meditite', 'Wingull', 'Shroomish', 'Marill', 'Roselia', 'Skitty', 'Goldeen', 'Oddish', 'Illumise', 'Seedot', 'Volbeat'], encounterRatesPercent: {'Oddish': 40, 'Poochyena': 30, 'Illumise': 18, 'Marill': 10, 'Seedot': 1, 'Volbeat': 1}, items: ['Wepear Berry', 'Revive', 'Great Ball', 'Repel']),
  GuideStep(section: 'Slateport i trzecia odznaka', title: 'Połącz Rusturf Tunnel', description: 'Przejdź przez Route 117 do Verdanturf Town. Użyj Rock Smash, aby usunąć skały w Rusturf Tunnel i połączyć obie strony tunelu.', location: 'Verdanturf Town / Rusturf Tunnel'),
  GuideStep(section: 'Fallarbor i czwarta odznaka', title: 'Oczyść południową część Route 111', description: 'Na południowym odcinku pokonaj Camper Tyrona (Sandshrew Lv.19), Aroma Lady Celinę (Roselia Lv.18), Picnicker Biancę (Shroomish Lv.18) i Kindlera Haydena (Numel Lv.18). Bianca i Hayden oraz Tyron i Celina mogą walczyć jako pary Double Battle. Przy Winstrate House czeka też rodzina Winstrate: cztery walki z rzędu bez możliwości leczenia pomiędzy nimi. Po zwycięstwie odbierz Macho Brace od Victorii. Na odcinku z Rock Smash można spotkać Gabby i Ty’ego, a także Picnicker Irene (Shroomish, Marill Lv.17) i Camper Travisa (Sandshrew Lv.18).', location: 'Route 111 — south', pokemon: ['Sandshrew', 'Roselia', 'Shroomish', 'Numel', 'Magnemite', 'Whismur', 'Marill', 'Taillow', 'Zigzagoon', 'Meditite'], items: ['Elixir', 'Macho Brace']),
  GuideStep(section: 'Fallarbor i czwarta odznaka', title: 'Przejdź południową część Route 112', description: 'Na południowej części trasy pokonaj Camper Larry’ego (Nuzleaf Lv.18), Picnicker Carol (Taillow i Lombre Lv.17), Hiker Trenta (trzy Geodude Lv.16–17) oraz Hiker Brice’a (Numel i Machop Lv.17). Trasa prowadzi do wejścia do Fiery Path; kolejka na Mt. Chimney jest na razie zablokowana przez Team Magma.', location: 'Route 112 — south', pokemon: ['Nuzleaf', 'Taillow', 'Lombre', 'Geodude', 'Numel', 'Machop'], encounterRatesPercent: {'Numel': 75, 'Marill': 25}),
  GuideStep(section: 'Fallarbor i czwarta odznaka', title: 'Przejdź przez Fiery Path', description: 'Przejdź głównym korytarzem jaskini na drugą stronę góry. Boczne przejścia są na razie zablokowane głazami i wrócisz do nich po zdobyciu odpowiedniej umiejętności. Spotkania w jaskini: Numel 30%, Koffing 25%, Torkoal 18%, Machop 15%, Slugma 10% i Grimer 2%.', location: 'Fiery Path', pokemon: ['Numel', 'Koffing', 'Torkoal', 'Machop', 'Slugma', 'Grimer'], encounterRatesPercent: {'Numel': 30, 'Koffing': 25, 'Torkoal': 18, 'Machop': 15, 'Slugma': 10, 'Grimer': 2}),
  GuideStep(section: 'Fallarbor i czwarta odznaka', title: 'Zbierz jagody na północnej części Route 112', description: 'Po wyjściu z Fiery Path pokonaj Kindlera Bryanta (Numel i Slugma Lv.18) oraz Aroma Lady Shaylę (Shroomish i Roselia Lv.18). Mogą rozpocząć Double Battle. Zbierz jagody przy północnym wyjściu z jaskini.', location: 'Route 112 — north', pokemon: ['Numel', 'Slugma', 'Shroomish', 'Roselia'], items: ['Pecha Berry ×4', 'Rawst Berry ×4']),
  GuideStep(section: 'Fallarbor i czwarta odznaka', title: 'Pokonaj trenerów na północnej części Route 111', description: 'Pokonaj Cooltrainera Wiltona (Electrike, Wailmer i Makuhita Lv.17), Cooltrainer Brooke (Wingull, Numel i Roselia Lv.17) oraz Black Belta Daisuke (Machop Lv.19; wymagany Mach Bike). Starsza kobieta w domu przy trasie może bezpłatnie wyleczyć całą drużynę. Zbierz TM43 od chłopca przy drzewie Secret Base oraz jagody w pobliżu domu.', location: 'Route 111 — north', pokemon: ['Electrike', 'Wailmer', 'Makuhita', 'Wingull', 'Numel', 'Roselia', 'Machop'], items: ['TM43 Secret Power', 'Razz Berry', 'Oran Berry ×4', 'Razz Berry ×6']),
  GuideStep(section: 'Fallarbor i czwarta odznaka', title: 'Pokonaj trenerów i zbierz popiół na Route 113', description: 'Na trasie pokrytej popiołem spotkasz: Youngstera Jaylena (Trapinch Lv.19), Camper Lawrence’a (Baltoy i Sandshrew Lv.18), Ninja Boya Lunga (Koffing i Ninjask Lv.18), PokéManiaca Wyatta (dwa Aron Lv.18), Parasol Lady Madeline (Numel Lv.19), Twins Tori i Tia (dwa Spinda Lv.19), Ninja Boya Lao (trzy Koffing Lv.17), Youngstera Dillona (Aron Lv.19), Picnicker Sophie (Marill i Lombre Lv.17–19) oraz Bird Keepera Coby’ego (Skarmory i Swellow Lv.17–19). Lawrence i Lung oraz Sophie i Coby mogą walczyć w Double Battle. Spotkania w trawie: Spinda 70%, Slugma 25%, Skarmory 5%.', location: 'Route 113', pokemon: ['Trapinch', 'Baltoy', 'Sandshrew', 'Koffing', 'Ninjask', 'Aron', 'Numel', 'Spinda', 'Marill', 'Lombre', 'Skarmory', 'Swellow', 'Slugma'], encounterRatesPercent: {'Spinda': 70, 'Slugma': 25, 'Skarmory': 5}, items: ['Ether', 'Nugget', 'Super Repel', 'Max Ether', 'Soot Sack', 'TM32 Double Team', 'Hyper Potion']),
  GuideStep(section: 'Fallarbor i czwarta odznaka', title: 'Odbierz Soot Sack i poznaj warsztat szkła', description: 'W Glass Workshop odbierz Soot Sack. Przechodź przez popiół na trawie, aby zbierać pył wulkaniczny. Właściciel wymienia go na przedmioty: Blue Flute (250 kroków), Yellow Flute (500), Red Flute (500), White Flute (1000), Black Flute (1000), Pretty Chair (6000) i Pretty Desk (8000). Ukryte przedmioty na trasie leżą w kopcach popiołu.', location: 'Route 113 — Glass Workshop', items: ['Soot Sack', 'Blue Flute', 'Yellow Flute', 'Red Flute', 'White Flute', 'Black Flute', 'Pretty Chair', 'Pretty Desk']),
  GuideStep(section: 'Fallarbor i czwarta odznaka', title: 'Uzupełnij zadania w Fallarbor Town', description: 'W Pokémon Center spotkasz Lanette, która zaprosi cię do swojego domu na Route 114. W Poké Mart dziewczyna może jednorazowo nauczyć Pokémon Metronome. Move Maniac w północno-zachodnim domu przywraca zapomniany ruch za jedną Heart Scale. Możesz też spróbować Battle Tent — trzy kolejne zwycięstwa dają Hyper Potion. W kraterze przy laboratorium Profesora Cozmo znajdziesz ukryty Nugget.', location: 'Fallarbor Town', items: ['Nugget (ukryty)', 'Hyper Potion']),
  GuideStep(section: 'Fallarbor i czwarta odznaka', title: 'Pokonaj trenerów na Route 114', description: 'Na trasie do Meteor Falls pokonaj Fishermana Nolana (Barboach Lv.19), Picnicker Charlotte (Nuzleaf Lv.19), Fishermana Kaia (Barboach Lv.19), Fishermana Claude’a (Magikarp Lv.16, Goldeen Lv.17, Barboach Lv.18), Picnicker Nancy (Marill i Lombre Lv.18), Sr. and Jr. Tyrę i Ivy (Roselia Lv.18, Graveler Lv.20), Camper Shane’a (Sandshrew i Nuzleaf Lv.18), PokéManiaca Steve’a (Aron Lv.19), Kindlera Berniego (Slugma i Wingull Lv.18), Hiker Lucasa (Geodude i Numel Lv.18), Picnicker Angelinę (Lombre i Marill Lv.18) oraz Hiker Lenny’ego (Geodude i Machop Lv.18). Charlotte i Kai oraz Lucas i Angelina mogą walczyć w Double Battle. Spotkania w trawie: Swablu 40%, Lotad 30%, Lombre 20%, Seviper 9%, Nuzleaf 1%.', location: 'Route 114', pokemon: ['Barboach', 'Nuzleaf', 'Magikarp', 'Goldeen', 'Marill', 'Lombre', 'Roselia', 'Graveler', 'Sandshrew', 'Aron', 'Slugma', 'Wingull', 'Geodude', 'Numel', 'Machop', 'Swablu', 'Lotad', 'Seviper'], encounterRatesPercent: {'Swablu': 40, 'Lotad': 30, 'Lombre': 20, 'Seviper': 9, 'Nuzleaf': 1}, items: ['TM28 Dig', 'TM05 Roar', 'EnergyPowder', 'Revive (ukryty)', 'Persim Berry ×6', 'Lotad Doll', 'Carbos (ukryty)', 'Protein']),
  GuideStep(section: 'Fallarbor i czwarta odznaka', title: 'Zbadaj Meteor Falls i poznaj plany rywalizujących zespołów', description: 'Wejdź do Meteor Falls od strony Route 114. Przy moście spotkasz dwóch członków Team Magma, którzy ukradli Meteorite Profesorowi Cozmo. Pojawi się Archie z Team Aqua, zapowiadając pościg za złodziejami. Zbierz Full Heal przy północnej części wejścia oraz Moon Stone na wzgórzu na północny zachód od mostu. Zwykłe spotkania w jaskini: Zubat 80% i Solrock 20%; Old Rod: Magikarp 70%, Goldeen 30%.', location: 'Meteor Falls — 1F', pokemon: ['Zubat', 'Solrock', 'Magikarp', 'Goldeen'], encounterRatesPercent: {'Zubat': 80, 'Solrock': 20}, items: ['Full Heal', 'Moon Stone']),
  GuideStep(section: 'Fallarbor i czwarta odznaka', title: 'Zbadaj południową część Route 115', description: 'Na odcinku przy Rustboro pokonaj Black Belta Noba (Machop Lv.19), Collector Hectora (Zangoose i Seviper Lv.18), Psychic Marlene (Meditite i Spoink Lv.18) oraz Battle Girl Cyndy (Meditite i Makuhita Lv.18). Hector i Marlene mogą walczyć w Double Battle. Zbierz Super Potion na plaży, Great Ball za skałami wymagającymi Rock Smash, sześć Bluk Berries, PP Up oraz ukryty Heart Scale przy Cyndy. Old Rod pozwala złowić Magikarp 70% lub Tentacool 30%.', location: 'Route 115 — south', pokemon: ['Machop', 'Zangoose', 'Seviper', 'Meditite', 'Spoink', 'Makuhita', 'Magikarp', 'Tentacool'], encounterRatesPercent: {'Magikarp': 70, 'Tentacool': 30}, items: ['Super Potion', 'Great Ball', 'Bluk Berry ×6', 'PP Up', 'Heart Scale (ukryty)']),
  GuideStep(section: 'Fallarbor i czwarta odznaka', title: 'Zatrzymaj Team Magma na Mt. Chimney', description: 'Wjedź kolejką linową na Mt. Chimney. Pokonaj członków Team Magma, Tabithę i Maxiego. Następnie zejdź przez Jagged Pass do Lavaridge Town.', location: 'Mt. Chimney / Jagged Pass', pokemon: ['Mightyena', 'Zubat', 'Camerupt', 'Numel']),
  GuideStep(section: 'Fallarbor i czwarta odznaka', title: 'Pokonaj Flannery', description: 'Flannery specjalizuje się w typie Fire. Wykorzystaj ruchy Water, Ground lub Rock. Po zwycięstwie otrzymasz Heat Badge i TM50 Overheat; rywal przekaże ci Go-Goggles.', location: 'Lavaridge Gym', pokemon: ['Numel', 'Slugma', 'Camerupt', 'Torkoal'], items: ['Heat Badge', 'TM50 Overheat', 'Go-Goggles']),
  GuideStep(section: 'Piąta odznaka i Norman', title: 'Zbadaj pustynię Route 111', description: 'Dzięki Go-Goggles możesz wejść na pustynię. Zbadaj Mirage Tower i wybierz jedną z dwóch skamielin: Root Fossil albo Claw Fossil. Drugą będzie można zdobyć później w Desert Underpass.', location: 'Route 111 / Mirage Tower', items: ['Root Fossil lub Claw Fossil']),
  GuideStep(section: 'Piąta odznaka i Norman', title: 'Wróć do Petalburg City', description: 'Po zdobyciu czterech odznak wróć do Petalburg City i przygotuj się do walki z Normanem.', location: 'Petalburg City'),
  GuideStep(section: 'Piąta odznaka i Norman', title: 'Pokonaj Normana', description: 'Norman używa Pokémonów typu Normal. Fighting jest skuteczny. Uważaj na Truant Slakinga — wykorzystuj turę, w której nie atakuje. Po zwycięstwie otrzymasz Balance Badge i TM42 Facade. Rodzina Wally’ego przekaże HM03 Surf.', location: 'Petalburg Gym', pokemon: ['Spinda', 'Vigoroth', 'Linoone', 'Slaking'], items: ['Balance Badge', 'TM42 Facade', 'HM03 Surf']),
  GuideStep(section: 'Piąta odznaka i Norman', title: 'Wróć na Route 115 po zdobyciu Surf', description: 'Po zdobyciu HM03 Surf wróć na północną część Route 115 i zbadaj plażę, leśny labirynt oraz mały skrawek trawy na północnym zachodzie. Pokonaj trenerów dostępnych od strony wody: Ninja Boya Jaiena (Ninjask i Gulpin Lv.26), Experta Timothy’ego (Hariyama Lv.27), Triathlete Kyrę (Doduo i Dodrio Lv.26) oraz Black Belta Koichiego (Machop Lv.24 i Machoke Lv.28). Nie łącz tej późniejszej eksploracji z pierwszym przejściem trasy. Spotkania w trawie: Taillow 40%, Swablu 30%, Jigglypuff 10%, Swellow 10%, Wingull 10%. Surf: Tentacool 60%, Wingull 35%, Pelipper 5%. Old Rod: Magikarp 70%, Tentacool 30%; Good Rod: Magikarp 60%, Tentacool 20%, Wailmer 20%; Super Rod: Wailmer 100%.', location: 'Route 115 — north (Surf)', pokemon: ['Ninjask', 'Gulpin', 'Hariyama', 'Doduo', 'Dodrio', 'Machop', 'Machoke', 'Taillow', 'Swablu', 'Jigglypuff', 'Swellow', 'Wingull', 'Tentacool', 'Pelipper', 'Magikarp', 'Wailmer'], encounterRatesPercent: {'Taillow': 40, 'Swablu': 30, 'Jigglypuff': 10, 'Swellow': 10, 'Wingull': 10}, items: ['TM01 Focus Punch', 'Heal Powder', 'Iron', 'Kelpsy Berry ×6']),

  GuideStep(section: 'Fortree i szósta odznaka', title: 'Pokonaj trenerów na zachodniej części Route 118', description: 'Na zachodnim brzegu pokonaj czterech trenerów: Aroma Lady Rose — Roselia, Shroomish i Roselia Lv.14; Youngster Deandre — Zigzagoon, Aron i Electrike Lv.14; Fisherman Wade — Tentacool Lv.16; Guitarist Dalton — Magnemite i Whismur Lv.15. Rose i Deandre mogą walczyć w Double Battle. Zbierz ukryty Heart Scale na plaży przy Fisherman Wade. Na tym etapie dostępne są także spotkania wędkarskie: Old Rod — Magikarp 70%, Tentacool 30%.', location: 'Route 118 — west side', pokemon: ['Roselia', 'Shroomish', 'Zigzagoon', 'Aron', 'Electrike', 'Tentacool', 'Magnemite', 'Whismur', 'Magikarp'], encounterRatesPercent: {'Magikarp': 70, 'Tentacool': 30}, items: ['Heart Scale']),
  GuideStep(section: 'Fortree i szósta odznaka', title: 'Przepraw się przez wschodnią część Route 118', description: 'Użyj Surf na wschód od Mauville i spotkaj Stevena. Na wschodnim brzegu odbierz Good Rod od rybaka. W wodzie możesz spotkać Tentacool i Wingull, a wędkowanie pozwala łowić Magikarp, Tentacool i Carvanha zależnie od wędki. Przygotuj Acro Bike, ponieważ część przedmiotów na Route 119 wymaga przejazdu po wąskich szynach.', location: 'Route 118 — east', pokemon: ['Steven'], items: ['Good Rod', 'Heart Scale (ukryty)', 'Hyper Potion (ukryty)']),
  GuideStep(section: 'Fortree i szósta odznaka', title: 'Przejdź przez południową i środkową Route 119', description: 'Na długiej trawie pokonaj Bug Catchera Kenta (Ninjask Lv.25), Bug Maniaca Donalda (Wurmple, Silcoon i Beautifly Lv.24), Bug Catchera Grega (Volbeat i Illumise Lv.25), Bug Maniaca Taylora (Wurmple, Cascoon i Dustox Lv.27), Bug Catchera Douga (Nincada i Ninjask Lv.28), Bug Maniaca Brenta (Surskit Lv.26), Pokémon Ranger Catherine (Gloom i Roselia Lv.26), Pokémon Ranger Jacksona (Breloom Lv.27), Parasol Lady Rachel (Goldeen Lv.26), Bird Keepera Phila (Swellow Lv.26), Ninja Boya Takashiego (Ninjask i Koffing Lv.25), Kindlera Daytona (Slugma i Numel Lv.25) oraz Bird Keepera Hugh (Wingull i Tropius Lv.25). Rachel i Phil oraz Takashi i Dayton mogą walczyć w Double Battle. Trawa: Oddish 30%, Zigzagoon 30%, Linoone 30%, Tropius 9%, Kecleon 1%. Surf: Tentacool 60%, Wingull 35%, Pelipper 5%.', location: 'Route 119 — south and middle', pokemon: ['Ninjask', 'Wurmple', 'Silcoon', 'Beautifly', 'Volbeat', 'Illumise', 'Cascoon', 'Dustox', 'Nincada', 'Surskit', 'Gloom', 'Roselia', 'Breloom', 'Goldeen', 'Swellow', 'Koffing', 'Slugma', 'Numel', 'Wingull', 'Tropius', 'Oddish', 'Zigzagoon', 'Linoone', 'Kecleon', 'Tentacool', 'Pelipper'], encounterRatesPercent: {'Oddish': 30, 'Zigzagoon': 30, 'Linoone': 30, 'Tropius': 9, 'Kecleon': 1}, items: ['Super Repel', 'Full Heal (ukryty)', 'Hyper Potion ×2', 'Sitrus Berry ×2', 'Leppa Berry ×2', 'Elixir']),
  GuideStep(section: 'Fortree i szósta odznaka', title: 'Zbadaj Feebasowe łowiska i boczne ścieżki Route 119', description: 'Po zdobyciu Surf sprawdź wodne odnogi trasy i zbierz Zinc. Feebas występuje wyłącznie na sześciu losowo wyznaczonych polach wody Route 119. Można go łowić dowolną wędką, a na właściwym polu ma 50% szansy na spotkanie. Pola zmieniają się po zmianie modnego powiedzenia w Dewford Town. Po odblokowaniu przejścia wróć także po przedmioty za rzeką i przy wodospadach. Do Calcium w sekretnym przejściu potrzebny jest Acro Bike.', location: 'Route 119 — river and waterfalls', pokemon: ['Feebas', 'Magikarp', 'Tentacool', 'Carvanha', 'Wingull', 'Pelipper'], items: ['Zinc', 'Calcium (ukryty, Acro Bike)', 'Ultra Ball (ukryty)', 'Leaf Stone', 'Max Ether (ukryty)', 'Elixir']),

  GuideStep(section: 'Fortree i szósta odznaka', title: 'Oczyść pierwsze piętro Weather Institute', description: 'Wejdź do budynku zajętego przez Team Aqua. Na 1F pokonaj Grunta z Carvanhą Lv.28 oraz Grunta z Zubatem i Poochyeną Lv.27. W północno-zachodnim pokoju znajduje się łóżko, które bezpłatnie leczy całą drużynę; obok jest komputer. Skorzystaj z leczenia przed wejściem na drugie piętro.', location: 'Weather Institute — 1F', pokemon: ['Carvanha', 'Zubat', 'Poochyena']),
  GuideStep(section: 'Fortree i szósta odznaka', title: 'Pokonaj Team Aqua na drugim piętrze Weather Institute', description: 'Na 2F pokonaj dwóch Gruntów, którzy mogą rozpocząć Double Battle: jeden używa Poochyenyi i Carvanhy Lv.27, drugi Zubata i Poochyenyi Lv.27. Ostatni Grunt ma Poochyenę, Zubata i Carvanhę Lv.26. Następnie zmierz się z Aqua Admin Shelly: Carvanha Lv.28 (Rough Skin) i Mightyena Lv.28 (Intimidate). Unikaj ataków kontaktowych przeciw Carvanhie, jeśli nie chcesz otrzymywać obrażeń od Rough Skin. Po zwycięstwie Team Aqua opuści budynek.', location: 'Weather Institute — 2F', pokemon: ['Poochyena', 'Carvanha', 'Zubat', 'Mightyena']),
  GuideStep(section: 'Fortree i szósta odznaka', title: 'Odbierz Castforma i przejdź przez północną Route 119', description: 'Porozmawiaj z głównym naukowcem na drugim piętrze i odbierz Castforma trzymającego Mystic Water. Jeśli drużyna jest pełna, zwolnij miejsce przy komputerze na 1F i wróć po prezent. Po wyjściu z instytutu pokonaj Guitarista Fabiana (Manectric Lv.26), Ninja Boya Yasu (Ninjask Lv.26) oraz Ninja Boya Hideo (dwa Koffing Lv.25). Fabian i Yasu mogą walczyć w Double Battle. Przejdź przez odblokowany most i przygotuj się na walkę z rywalem.', location: 'Weather Institute / Route 119 — north', pokemon: ['Castform', 'Manectric', 'Ninjask', 'Koffing'], items: ['Castform', 'Mystic Water']),
  GuideStep(section: 'Fortree i szósta odznaka', title: 'Pokonaj rywala na Route 119 i odbierz HM02 Fly', description: 'Po wyjściu z Weather Institute rywal Brendan lub May zatrzyma cię przy schodach. Jego drużyna zależy od wybranego startera: zawsze ma Pelippera Lv.29 i Lombre Lv.29, a trzeci Pokémon to Combusken, Marshtomp albo Slugma Lv.31. Po zwycięstwie otrzymasz HM02 Fly oraz wpis rywala w PokéNav Match Call. Przejdź dalej do Fortree City.', location: 'Route 119 — north bridge', pokemon: ['Pelipper', 'Lombre', 'Combusken', 'Marshtomp', 'Slugma'], items: ['HM02 Fly']),

  GuideStep(section: 'Fortree i szósta odznaka', title: 'Zbadaj Route 120 i pokonaj trenerów', description: 'Wróć do Fortree i rusz na wschód. Na Route 120 spotkasz Parasol Lady Clarissę (Roselia i Wailmer Lv.28), ekipę Gabby i Ty (Magneton i Loudred Lv.30), Bird Keepera Roberta (Swablu Lv.29), Bird Keepera Colina (Wingull i Natu Lv.28), Cooltrainerów Leonela (Manectric Lv.30) i Jennifer (Sableye Lv.30), Parasol Lady Angelicę (Castform Lv.30), Ninja Boyów Riley’a i Keigo (Nincada/Koffing oraz Koffing/Ninjask Lv.28), Battle Girl Callie (Meditite i Makuhita Lv.28), Pokémon Rangerów Jennę i Lorenzo (trójki Lotad/Lombre/Nuzleaf oraz Seedot/Nuzleaf/Lombre Lv.28), Bug Maniaca Jeffreya (trzy Surskit Lv.27) i Ruin Maniaca Chipa (Baltoy, Sandshrew i Sandslash Lv.27). Część par może rozpocząć Double Battle. Spotkania w długiej trawie: Mightyena 30%, Oddish 25%, Poochyena 20%, Marill 15%, Absol 8%, Seedot 1%, Kecleon 1%.', location: 'Route 120', pokemon: ['Roselia', 'Wailmer', 'Magneton', 'Loudred', 'Swablu', 'Wingull', 'Natu', 'Manectric', 'Sableye', 'Castform', 'Nincada', 'Koffing', 'Meditite', 'Makuhita', 'Lotad', 'Lombre', 'Nuzleaf', 'Seedot', 'Surskit', 'Baltoy', 'Sandshrew', 'Sandslash', 'Mightyena', 'Oddish', 'Poochyena', 'Marill', 'Absol', 'Kecleon'], encounterRatesPercent: {'Mightyena': 30, 'Oddish': 25, 'Poochyena': 20, 'Marill': 15, 'Absol': 8, 'Seedot': 1, 'Kecleon': 1}, items: ['Rare Candy (ukryty, wymaga Cut)', 'Revive (ukryty)']),
  GuideStep(section: 'Fortree i szósta odznaka', title: 'Zbadaj wodę Route 120, Scorched Slab i ukryte Kecleony', description: 'Na Route 120 spotkasz sześć niewidzialnych Kecleonów — po zdobyciu Devon Scope możesz je ujawniać i łapać lub pokonywać. Na północnym jeziorze wejdź do Scorched Slab i odbierz TM11 Sunny Day. Surf: Marill 99%, Goldeen 1%. Old Rod: Magikarp 70%, Goldeen 30%. Good Rod: Magikarp 60%, Goldeen 20%, Barboach 20%. Wróć po Devon Scope po Nest Ball przy północnym brzegu jeziora, Aspear Berries ×6, Revive, ukryty Zinc, Nugget, Pecha Berries ×6, Nanab/Pinap/Wepear/Razz Berries ×3 oraz Full Heal i ukryty Rare Candy dostępne z Surf. Beauty przy zachodniej odnodze daje jedną jagodę dziennie: Figy, Wiki, Mago, Aguav lub Iapapa zależnie od ostatniej cyfry Trainer ID. Wejście do Ancient Tomb pozostaje zamknięte do rozwiązania zagadki Sealed Chamber.', location: 'Route 120 / Scorched Slab / Ancient Tomb', pokemon: ['Kecleon', 'Marill', 'Goldeen', 'Magikarp', 'Barboach'], encounterRatesPercent: {'Marill': 99, 'Goldeen': 1}, items: ['TM11 Sunny Day', 'Devon Scope', 'Nest Ball', 'Aspear Berry ×6', 'Revive', 'Zinc (ukryty)', 'Nugget', 'Pecha Berry ×6', 'Nanab Berry ×3', 'Pinap Berry ×3', 'Wepear Berry ×3', 'Razz Berry ×3', 'Full Heal', 'Rare Candy (ukryty)']),
  GuideStep(section: 'Fortree i szósta odznaka', title: 'Ukończ Fortree Gym i pokonaj Winonę', description: 'Po użyciu Devon Scope usuń Kecleona blokującego wejście do Gymu. Obracaj drewniane zapory, przechodząc przez kolejne przejścia; niektóre trzeba obrócić w określonym kierunku, aby otworzyć drogę. Trenerzy: Bird Keeper Humberto (Skarmory Lv.30), Bird Keeper Jared (Doduo, Skarmory i Tropius Lv.27), Picnicker Ashley (trzy Swablu Lv.27), Camper Flint (Swellow i Xatu Lv.29), Bird Keeper Edwardo (Doduo i Pelipper Lv.29), Bird Keeper Darius (Tropius Lv.30). Winona ma Swablu Lv.29 (Perish Song, Mirror Move, Safeguard, Aerial Ace), Tropius Lv.29 (Sunny Day, Aerial Ace, SolarBeam, Synthesis), Pelipper Lv.30 (Water Gun, Supersonic, Protect, Aerial Ace), Skarmory Lv.31 (Sand-Attack, Fury Attack, Steel Wing, Aerial Ace) i Altarię Lv.33 (Earthquake, DragonBreath, Dragon Dance, Aerial Ace; Oran Berry). Uważaj na Sunny Day i Dragon Dance Altarii. Ataki Electric są dobre na większość drużyny, ale Altaria jako Dragon/Flying otrzymuje od nich tylko zwykłe obrażenia; Ice jest na nią szczególnie skuteczny. Po wygranej otrzymasz Feather Badge, TM40 Aerial Ace i możliwość używania Fly poza walką.', location: 'Fortree Gym', pokemon: ['Skarmory', 'Doduo', 'Tropius', 'Swablu', 'Swellow', 'Xatu', 'Pelipper', 'Altaria'], items: ['Feather Badge', 'TM40 Aerial Ace']),
  GuideStep(section: 'Lilycove i Team Magma', title: 'Przejdź Route 121 i oczyść drogę do Safari Zone', description: 'Na Route 121 pokonaj Bug Maniaca Cale’a (Dustox i Beautifly Lv.29), Hex Maniac Tammy (Duskull i Shuppet Lv.29), Beauty Jessicę (Kecleon i Seviper Lv.29), Sr. and Jr. Kate & Joy (Spinda Lv.30 i Slaking Lv.32), Pokémon Breederów Pat i Myles (po sześć Pokémonów Lv.25: Poochyena, Shroomish, Electrike, Marill, Sandshrew, Gulpin oraz Makuhita, Wingull, Tropius, Zigzagoon, Electrike, Numel), Gentleman Waltera (Manectric Lv.29), Pokéfan Vanessę (Pikachu Lv.30 z Oran Berry) oraz Cooltrainerów Marcela (Manectric i Shiftry Lv.29) i Cristin (Loudred i Vigoroth Lv.29). Cale i Tammy oraz Pat i Myles mogą walczyć podwójnie; Marcel i Cristin także mogą uruchomić Double Battle. Trawa: Shuppet 30%, Poochyena 20%, Mightyena 20%, Oddish 15%, Wingull 9%, Gloom 5%, Kecleon 1%. Zbierz jagody w północno-zachodnim i południowo-wschodnim grządce, HP Up, Zinc, Revive, Carbos, ukryty Nugget, ukryty Full Heal i ukryty Max Revive. Wejście do Safari Zone znajduje się na północy trasy.', location: 'Route 121', pokemon: ['Dustox', 'Beautifly', 'Duskull', 'Shuppet', 'Kecleon', 'Seviper', 'Spinda', 'Slaking', 'Poochyena', 'Shroomish', 'Electrike', 'Marill', 'Sandshrew', 'Gulpin', 'Makuhita', 'Wingull', 'Tropius', 'Zigzagoon', 'Numel', 'Manectric', 'Pikachu', 'Shiftry', 'Loudred', 'Vigoroth', 'Mightyena', 'Oddish', 'Gloom'], encounterRatesPercent: {'Shuppet': 30, 'Poochyena': 20, 'Mightyena': 20, 'Oddish': 15, 'Wingull': 9, 'Gloom': 5, 'Kecleon': 1}, items: ['Aspear Berry ×2', 'Chesto Berry ×2', 'Persim Berry ×2', 'Rawst Berry ×2', 'HP Up (ukryty)', 'Zinc', 'Revive', 'Carbos', 'Nugget (ukryty, Cut)', 'Full Heal (ukryty)', 'Max Revive (ukryty)', 'Nanab Berry ×6']),
  GuideStep(section: 'Lilycove i Team Magma', title: 'Przepłyń Route 122 i przygotuj się do Mt. Pyre', description: 'Z południowego wybrzeża Route 121 użyj Surf, aby dotrzeć do Mt. Pyre na Route 122. Na wodzie spotkasz Tentacool 60%, Wingull 35% i Pelipper 5%. Old Rod: Magikarp 70%, Tentacool 30%. Good Rod: Magikarp 60%, Tentacool 20%, Wailmer 20%. Zanim wejdziesz do góry, upewnij się, że masz wolne miejsce w drużynie na ewentualne Pokémony i zapas Poké Balli. Mt. Pyre ma część wewnętrzną z piętrami oraz zewnętrzną ścieżkę prowadzącą na szczyt.', location: 'Route 122', pokemon: ['Tentacool', 'Wingull', 'Pelipper', 'Magikarp', 'Wailmer'], encounterRatesPercent: {'Tentacool': 60, 'Wingull': 35, 'Pelipper': 5}),
  GuideStep(section: 'Lilycove i Team Magma', title: 'Zbadaj wnętrze Mt. Pyre i zbierz przedmioty', description: 'Na piętrach 1F–6F spotkasz głównie Shuppet: na 1F–3F ma 100% udziału w spotkaniach (poziomy 22–29), a na 4F–6F Shuppet 90% i Duskull 10%. Pokonaj trenerów: PokéManiaca Marka (Rhyhorn Lv.31), Hex Maniac Leah (Spoink Lv.31), Black Belta Zandera (Hariyama Lv.31), parę Dez i Luke (Delcatty oraz Manectric Lv.31), Psychic Kaylę (Wobbuffet, Natu i Kadabra Lv.26), Pokémon Breeder Gabrielle (sześć Pokémonów Lv.26), Psychic Williama (dwa Ralts i Kirlia Lv.26), Hex Maniac Tashę (Shuppet Lv.32), Black Belta Atsushiego (Hariyama Lv.32), Hex Maniac Valerie (Sableye Lv.32) i Psychic Cedrica (Wobbuffet Lv.32). Wewnątrz odbierz Cleanse Tag od starszej kobiety na 1F, Ultra Ball na 2F, Super Repel na 3F, TM30 Shadow Ball na 6F, a następnie skorzystaj z dziury w podłodze, aby dostać się do Lax Incense na 5F i Sea Incense na 4F. Te dwa kadzidła leżą na odrębnych półkach dostępnych przez spadanie między piętrami.', location: 'Mt. Pyre — interior 1F–6F', pokemon: ['Shuppet', 'Duskull', 'Rhyhorn', 'Spoink', 'Hariyama', 'Delcatty', 'Manectric', 'Wobbuffet', 'Natu', 'Kadabra', 'Skitty', 'Poochyena', 'Zigzagoon', 'Lotad', 'Seedot', 'Taillow', 'Ralts', 'Kirlia', 'Sableye'], encounterRatesPercent: {'Shuppet': 90, 'Duskull': 10}, items: ['Cleanse Tag', 'Ultra Ball', 'Super Repel', 'TM30 Shadow Ball', 'Lax Incense', 'Sea Incense']),
  GuideStep(section: 'Lilycove i Team Magma', title: 'Wejdź na szczyt Mt. Pyre i odbierz Magma Emblem', description: 'Na zewnętrznym zboczu Mt. Pyre spotkasz Shuppet 60%, Vulpix 30% i Wingull 10%; na szczycie Shuppet 85%, Duskull 13% i rzadkie Chimecho 2%. Pokonaj czterech członków Team Aqua na szczycie, a następnie Archiego. Archie zabierze Red Orb, a opiekunka góry przekaże ci Magma Emblem pozostawiony przez Team Magma. Na zewnętrznej ścieżce zbierz TM48 Skill Swap i Max Potion; ukryte przedmioty to Max Ether i Ultra Ball. Na szczycie znajdziesz ukryty Zinc i Rare Candy. Po wydarzeniu możesz wrócić do Jagged Pass — Magma Emblem otworzy wejście do Magma Hideout.', location: 'Mt. Pyre — exterior and summit', pokemon: ['Shuppet', 'Vulpix', 'Wingull', 'Duskull', 'Chimecho', 'Carvanha', 'Zubat', 'Poochyena', 'Wailmer'], encounterRatesPercent: {'Shuppet': 85, 'Duskull': 13, 'Chimecho': 2}, items: ['TM48 Skill Swap', 'Max Potion', 'Max Ether (ukryty)', 'Ultra Ball (ukryty)', 'Zinc (ukryty)', 'Rare Candy (ukryty)', 'Magma Emblem', 'Red Orb']),
  GuideStep(section: 'Lilycove i Team Magma', title: 'Przejdź opcjonalną Route 123 od strony Mt. Pyre', description: 'Route 123 prowadzi z Route 122 na zachód do Route 118. Wymaga Cut do bocznych ścieżek; przydatny jest też Pokémon typu Grass, ponieważ dziewczyna przy ścieżce podaruje TM19 Giga Drain, gdy pokażesz jej takiego Pokémona. Pokonaj Hex Maniac Kindrę (Duskull i Shuppet Lv.30), Collectora Eda (Zangoose i Seviper Lv.30), Cooltrainer Wendy (Mawile, Roselia i Pelipper Lv.29), Cooltrainera Braxtona (Swellow, Trapinch, Wailmer, Magneton i Shiftry Lv.28), Guitarista Fernando (Electrike i Loudred Lv.30), Bird Keepera Alberta (Pelipper i Xatu Lv.30), Psychic Jacki (Kadabra i Lunatone Lv.30), Experta Fredricka (Makuhita i Machoke Lv.30), a po użyciu Cut także Psychic Camerona (Solrock Lv.31), Ninja Boya Jonasa (Koffing Lv.31) i Parasol Lady Kayley (Castform Lv.31). Kindra i Ed, Fernando i Alberto oraz Jacki i Fredrick mogą walczyć podwójnie; Jonas i Kayley mają wymuszoną Double Battle. Zbierz ukryte PP Up ×2 i Rare Candy, TM19, Pecha/Rawst/Sitrus Berries ×2, ukryty Hyper Potion, Leppa Berries ×4, Elixir, ukryty Super Repel, Revival Herb i Calcium.', location: 'Route 123 — east / Mt. Pyre side', pokemon: ['Duskull', 'Shuppet', 'Zangoose', 'Seviper', 'Mawile', 'Roselia', 'Pelipper', 'Swellow', 'Trapinch', 'Wailmer', 'Magneton', 'Shiftry', 'Electrike', 'Loudred', 'Xatu', 'Kadabra', 'Lunatone', 'Makuhita', 'Machoke', 'Solrock', 'Koffing', 'Castform'], items: ['PP Up ×2', 'Rare Candy (ukryty)', 'TM19 Giga Drain', 'Pecha Berry ×2', 'Rawst Berry ×2', 'Sitrus Berry ×2', 'Hyper Potion (ukryty)', 'Leppa Berry ×4', 'Elixir', 'Super Repel (ukryty)', 'Revival Herb', 'Calcium']),
  GuideStep(section: 'Lilycove i Team Magma', title: 'Uzupełnij spotkania i przedmioty na Route 123', description: 'Spotkania w trawie na Route 123: Shuppet 30%, Poochyena 20%, Mightyena 20%, Oddish 15%, Wingull 9%, Gloom 5%, Kecleon 1%. Surf: Tentacool 60%, Wingull 35%, Pelipper 5%. Old Rod: Magikarp 70%, Tentacool 30%. Good Rod: Magikarp 60%, Tentacool 20%, Wailmer 20%. Na zachodnim końcu odwiedź dom Berry Mastera i ogród; Berry Master może dać jagody, a jego żona po specjalnych hasłach przyznaje rzadkie jagody. Teren ma kilka poziomów i uskoki, więc nie wszystkie boczne ścieżki da się przejść z jednej strony — sprawdź oba dojścia od Route 118 i Route 122. Pamiętaj, że ten odcinek jest opcjonalny i można go dokończyć podczas późniejszego powrotu.', location: 'Route 123 — full route / Berry Master’s House', pokemon: ['Shuppet', 'Poochyena', 'Mightyena', 'Oddish', 'Wingull', 'Gloom', 'Kecleon', 'Tentacool', 'Pelipper', 'Magikarp', 'Wailmer'], encounterRatesPercent: {'Shuppet': 30, 'Poochyena': 20, 'Mightyena': 20, 'Oddish': 15, 'Wingull': 9, 'Gloom': 5, 'Kecleon': 1}, optional: true),
  GuideStep(section: 'Lilycove i Team Magma', title: 'Otwórz Magma Hideout na Jagged Pass', description: 'Po otrzymaniu Magma Emblem na Mt. Pyre poleć do Lavaridge Town. Wróć na Jagged Pass od strony Route 112 albo skorzystaj z kolejki linowej na Mt. Chimney i zejdź na trasę. W miejscu, gdzie wcześniej stał Magma Grunt, emblemat otworzy ukryte wejście do bazy. Do przejścia pierwszej części potrzebujesz HM04 Strength. Przed wejściem wylecz drużynę i przygotuj Pokémony Water, Ground lub Fighting — baza zawiera wiele walk z Pokémonami Fire, Ground i Dark.', location: 'Jagged Pass / Magma Hideout entrance', items: ['Magma Emblem', 'HM04 Strength']),
  GuideStep(section: 'Lilycove i Team Magma', title: 'Przejdź przez Magma Hideout i pokonaj Gruntów', description: 'W bazie spotkasz Gruntów Team Magma na kilku poziomach. Ich składy obejmują Poochyenę Lv.29, Zubata Lv.29, Numela Lv.29, Mightyena Lv.29, parę Baltoy Lv.28 + Numel Lv.28 oraz Baltoy Lv.28 + Zubat Lv.28; dalej pojawiają się pary Numel Lv.29 + Mightyena Lv.29, samotne Zubaty i Poochyena Lv.29, Baltoy Lv.29 oraz Mightyena Lv.29. Kolejne walki na niższych poziomach obejmują Baltoy Lv.29, Numel Lv.29 i Zubat Lv.29. Łącznie przejście prowadzi przez liczne pojedynki, w tym kilka możliwych Double Battles. Dzikie Pokémony w jaskini: Geodude 55%, Torkoal 30%, Graveler 15%. Użyj Strength do przesuwania głazów i odwiedzaj boczne pomieszczenia przed zejściem głębiej.', location: 'Magma Hideout — entrance, 1F, B1F–B4F', pokemon: ['Poochyena', 'Zubat', 'Numel', 'Mightyena', 'Baltoy', 'Geodude', 'Torkoal', 'Graveler'], encounterRatesPercent: {'Geodude': 55, 'Torkoal': 30, 'Graveler': 15}, items: ['Rare Candy', 'Full Restore', 'Max Elixir', 'Nugget', 'PP Max', 'Max Revive', 'Escape Rope']),
  GuideStep(section: 'Lilycove i Team Magma', title: 'Pokonaj Tabithę i Maxiego — zatrzymaj plan Team Magma', description: 'Na B4F zatrzyma cię Magma Admin Tabitha. Jego drużyna: Numel Lv.26, Mightyena Lv.28, Zubat Lv.30 i Camerupt Lv.33. Po walce zbierz Max Revive i przejdź do komory Groudon. Maxie użyje Blue Orb, aby obudzić legendarnego Pokémona, który ucieknie. Następnie zmierz się z Maxiem: Mightyena Lv.37 (Roar, Swagger, Scary Face, Take Down), Crobat Lv.38 (Bite, Wing Attack, Confuse Ray, Air Cutter) i Camerupt Lv.39 (Take Down, Amnesia, Rock Slide, Earthquake). Water jest szczególnie skuteczny na Camerupta; Electric i Ice pomagają na Crobat. Po zwycięstwie Maxie ucieknie w poszukiwaniu Groudona. W drodze powrotnej zbierz Escape Rope i wyjdź z bazy.', location: 'Magma Hideout — B4F/B5F', pokemon: ['Numel', 'Mightyena', 'Zubat', 'Camerupt', 'Crobat', 'Groudon'], items: ['Max Revive', 'Blue Orb', 'Escape Rope']),
  GuideStep(section: 'Lilycove i Team Magma', title: 'Zatrzymaj kradzież łodzi podwodnej w Slateport Harbor', description: 'Po wyjściu z Magma Hideout poleć do Slateport City i udaj się do portu na północnym wschodzie. Kapitan Stern kończy wywiad telewizyjny i opowiada o odkrytej podwodnej jaskini na Route 128. Archie pojawia się z megafonem, po czym wchodzi do portu. W środku zastaniesz Archiego i Grunta przy łodzi podwodnej — Team Aqua ucieknie nią, zanim zdążysz ich zatrzymać. Archie zdradzi, że ich baza znajduje się w Lilycove City. To wydarzenie odblokowuje dalszy etap fabuły i wejście do Aqua Hideout.', location: 'Slateport City — Harbor', pokemon: ['Archie'], items: ['Submarine (fabuła)']),
  GuideStep(section: 'Lilycove i Team Magma', title: 'Zbadaj Lilycove City i odbierz przedmioty', description: 'Po dotarciu do Lilycove sprawdź plażę i domy przed wejściem do Aqua Hideout. Na wodzie Surf: Tentacool 60%, Wingull 35%, Pelipper 5%. Old Rod: Magikarp 70%, Tentacool 30%; Good Rod: Magikarp 60%, Tentacool 20%, Wailmer 20%. Zbierz Max Repel na południowo-wschodnim cyplu, TM44 Rest od śpiącego mężczyzny we wschodnim domu, ukrytą Poké Ball na płytkiej wodzie, ukryty Heart Scale na południowo-zachodniej plaży i ukryty PP Up przed wejściem do kryjówki. W Contest Hall odbierz Pokéblock Case od recepcjonistki. Odwiedź Move Deletera, który bezpłatnie usuwa ruchy HM, oraz Berry Gentlemana — daje jedną losową jagodę dziennie. Zanim podejdziesz do Department Store, przygotuj drużynę na opcjonalną ostatnią walkę z rywalem.', location: 'Lilycove City', pokemon: ['Tentacool', 'Wingull', 'Pelipper', 'Magikarp', 'Wailmer'], items: ['Max Repel', 'TM44 Rest', 'Poké Ball (ukryta)', 'Heart Scale (ukryty)', 'PP Up (ukryty)', 'Pokéblock Case', 'Daily Berry']),
  GuideStep(section: 'Lilycove i Team Magma', title: 'Pokonaj rywala przed Lilycove Department Store', description: 'May lub Brendan blokuje wejście do Department Store. To piąta i ostatnia walka z rywalem; skład zależy od startera gracza. Przy Treecko: Tropius Lv.31, Pelipper Lv.32, Ludicolo Lv.32 i Combusken Lv.34. Przy Torchic: Tropius Lv.31, Ludicolo Lv.32, Slugma Lv.32 i Marshtomp Lv.34. Przy Mudkip: Tropius Lv.31, Slugma Lv.32, Pelipper Lv.32 i Grovyle Lv.34. Tropius zna Stomp, Sweet Scent, Whirlwind i Magical Leaf; pozostałe Pokémony mają zestawy ruchów z ich aktualnego etapu rozwoju. Po zwycięstwie rywal wraca do Littleroot Town, a wejście do sklepu jest wolne. Następnie możesz korzystać z codziennej loterii i pięter sklepu.', location: 'Lilycove City — Department Store entrance', pokemon: ['Tropius', 'Pelipper', 'Ludicolo', 'Combusken', 'Slugma', 'Marshtomp', 'Grovyle']),
  GuideStep(section: 'Aqua Hideout i siódma odznaka', title: 'Włam się do Aqua Hideout i zbierz Master Ball', description: 'Wejdź do jaskini na północno-wschodnim krańcu plaży Lilycove. Na 1F pokonaj Grunta z Poochyeną Lv.32. Na B1F używaj paneli teleportacyjnych: najpierw wybierz wschodni panel w północno-wschodnim pomieszczeniu, aby dostać się do Max Elixir; wróć i użyj drugiego panelu. W korytarzu paneli kieruj się kolejno: lewy, środkowy, lewy, lewy. W gabinecie Archiego znajdziesz cztery kule: górna lewa to Master Ball, dolna lewa to Nugget, a dwie pozostałe są w rzeczywistości dzikimi Electrode Lv.30. Nie klikaj ich bez przygotowania. Pokonaj Gruntów: Carvanha Lv.32, Zubat Lv.31 + Carvanha Lv.31, Poochyena Lv.31 + Zubat Lv.31, Zubat Lv.32 oraz parę Zubat Lv.32 + Carvanha Lv.32. W pokoju łodzi podwodnej użyj panelu pośrodku, by zebrać Nest Ball, a następnie wróć i przejdź do końcowego pomieszczenia.', location: 'Aqua Hideout — 1F / B1F', pokemon: ['Poochyena', 'Carvanha', 'Zubat', 'Electrode'], items: ['Master Ball', 'Nugget', 'Max Elixir', 'Nest Ball']),
  GuideStep(section: 'Aqua Hideout i siódma odznaka', title: 'Pokonaj Aqua Admin Matta i opuść kryjówkę', description: 'W ostatniej sali pokonaj Aqua Admin Matta. Używa Mightyeny Lv.34 (Intimidate; Odor Sleuth, Roar, Swagger, Scary Face) i Golbata Lv.34 (Inner Focus; Astonish, Bite, Wing Attack, Confuse Ray). Po zwycięstwie Archie ucieknie łodzią podwodną. Wróć panelami do wejścia. Grunt i blokada z Wailmerów znikną z plaży, dzięki czemu możesz wypłynąć na wschodni ocean w kierunku Route 124. Kryjówka pozostaje dostępna, ale ukończenie tej sekwencji jest ważne dla dalszego pościgu za Archiem i wydarzeń w Mossdeep oraz Seafloor Cavern.', location: 'Aqua Hideout — submarine room', pokemon: ['Mightyena', 'Golbat'], items: ['Nest Ball']),
  GuideStep(section: 'Aqua Hideout i siódma odznaka', title: 'Przepłyń Route 124 i odwiedź Treasure Huntera', description: 'Z Lilycove wypłyń na wschód przez Route 124. Pokonaj Swimmer Grace (Marill Lv.34), Declana (Gyarados Lv.34), rodzeństwo Lila & Roy (Chinchou Lv.34 i Carvanha Lv.33), Swimmera Spencera (Tentacool i Wingull Lv.33), Jenny (Wailmer Lv.34), Chada (Tentacool i Wailmer Lv.33), Triathlete Isabellę (Staryu Lv.34) i Swimmera Rolanda (Carvanha Lv.34). Grace i Declan oraz Isabella i Roland mogą walczyć w Double Battle. Surf: Tentacool 60%, Wingull 35%, Pelipper 5%. Old Rod: Magikarp 70%, Tentacool 30%; Good Rod: Magikarp 60%, Tentacool 20%, Wailmer 20%; Super Rod: Wailmer 60%, Sharpedo 40%. Odwiedź dom Treasure Huntera na małej wyspie na południowym wschodzie — wymienia Shardy: Red na Fire Stone, Yellow na Thunder Stone, Blue na Water Stone, Green na Leaf Stone. Większość podwodnych przedmiotów zbierzesz dopiero po zdobyciu Dive.', location: 'Route 124', pokemon: ['Marill', 'Gyarados', 'Chinchou', 'Carvanha', 'Tentacool', 'Wingull', 'Wailmer', 'Staryu', 'Magikarp', 'Pelipper', 'Sharpedo'], encounterRatesPercent: {'Tentacool': 60, 'Wingull': 35, 'Pelipper': 5}, items: ['Red Shard → Fire Stone', 'Yellow Shard → Thunder Stone', 'Blue Shard → Water Stone', 'Green Shard → Leaf Stone']),
  GuideStep(section: 'Aqua Hideout i siódma odznaka', title: 'Zbadaj Mossdeep City i odbierz Super Rod', description: 'W Mossdeep porozmawiaj z Black Beltem w płytkiej wodzie na południowym zachodzie — raz nauczy wybranego Pokémona DynamicPunch. Chłopiec przed domem Stevena daje King’s Rock, a w południowo-wschodnim narożniku wyspy znajdziesz Net Ball. W domu na wschód od Gymu odbierz Super Rod. W Space Center marynarz podaruje Sun Stone. W domu przy schodach do Space Center porozmawiaj z Wingullem dostarczającym listy; później wróć do Fortree, aby odebrać Mental Herb od hodowcy. Spotkania Surf: Tentacool 60%, Wingull 35%, Pelipper 5%. Old Rod: Magikarp 70%, Tentacool 30%; Good Rod: Magikarp 60%, Tentacool 20%, Wailmer 20%; Super Rod: Wailmer 60%, Sharpedo 40%. Beldum Lv.5 jest prezentem dopiero po zostaniu Championem, w domu Stevena.', location: 'Mossdeep City', pokemon: ['Tentacool', 'Wingull', 'Pelipper', 'Magikarp', 'Wailmer', 'Sharpedo', 'Beldum'], encounterRatesPercent: {'Tentacool': 60, 'Wingull': 35, 'Pelipper': 5}, items: ['King’s Rock', 'Net Ball', 'Super Rod', 'Sun Stone', 'Mental Herb (po dostarczeniu listu)', 'Beldum Lv.5 (po Hall of Fame)']),
  GuideStep(section: 'Aqua Hideout i siódma odznaka', title: 'Przejdź zagadkę Mossdeep Gym i pokonaj trenerów', description: 'Gym prowadzi przez pokoje połączone panelami teleportacyjnymi; płytki zmieniają ustawienie obrotowych przeszkód. Trenerzy: Psychic Preston (Kirlia Lv.36), Psychic Maura (Kadabra Lv.36), Psychic Samantha (Xatu Lv.36), Psychic Blake (Girafarig Lv.36), Psychic Macey (Natu Lv.36), Gentleman Clifford (Girafarig Lv.36), Hex Maniac Kathleen (Kadabra Lv.36), Psychic Nicholas (Wobbuffet Lv.36), Gentleman Nate (Spoink Lv.36), Psychic Virgil (Ralts Lv.36), Hex Maniac Sylvia (Meditite Lv.36) i Psychic Hannah (Kirlia Lv.36). Wiele par może rozpocząć Double Battle. Trasa: użyj zachodniego panelu w pierwszym pokoju, potem fioletowej płytki na wschodzie i dwa razy zielonej na południu. W zachodnio-centralnym pokoju skorzystaj z lewego panelu do północno-zachodniego pokoju; niebieską płytkę aktywuj dwa razy, pomarańczową trzy razy, drugą niebieską trzy razy i pierwszą niebieską raz. Przejdź do ostatniego panelu prowadzącego do liderów.', location: 'Mossdeep Gym', pokemon: ['Kirlia', 'Kadabra', 'Xatu', 'Girafarig', 'Natu', 'Wobbuffet', 'Spoink', 'Ralts', 'Meditite']),
  GuideStep(section: 'Aqua Hideout i siódma odznaka', title: 'Pokonaj Tate i Lizę — zdobądź Mind Badge', description: 'Tate i Liza walczą jednocześnie w Double Battle. Ich drużyna: Claydol Lv.41 (Earthquake, AncientPower, Psychic, Light Screen), Xatu Lv.41 (Psychic, Sunny Day, Confuse Ray, Calm Mind), Lunatone Lv.42 (Light Screen, Psychic, Hypnosis, Calm Mind; Sitrus Berry) i Solrock Lv.42 (Sunny Day, SolarBeam, Psychic, Flamethrower; Sitrus Berry). Wszystkie cztery mają Levitate, więc Earthquake nie trafi. Dark jest odporny na Psychic i zadaje obrażenia super effective; Ghost również jest skuteczny. Surf uderza obu przeciwników naraz i jest dobry na Claydola, Lunatone oraz Solrock, ale uważaj na Xatu i jego Calm Mind. Po zwycięstwie otrzymasz Mind Badge, TM04 Calm Mind i możliwość używania Dive poza walką.', location: 'Mossdeep Gym', pokemon: ['Claydol', 'Xatu', 'Lunatone', 'Solrock'], items: ['Mind Badge', 'TM04 Calm Mind']),
  GuideStep(section: 'Aqua Hideout i siódma odznaka', title: 'Obroń Mossdeep Space Center przed Team Magma', description: 'Po zdobyciu Mind Badge zobacz Maxiego i Gruntów idących do Space Center. Pokonaj czterech Gruntów na 1F, a następnie trzech na 2F — te trzy walki odbywają się jedna po drugiej bez przerwy. Pierwsze składy obejmują Zubat Lv.31 + Poochyena Lv.31, Numel Lv.32, Baltoy Lv.32, Mightyena Lv.26 i Lv.28 oraz Numel Lv.30; na 2F pojawiają się Zubat Lv.32, Mightyena Lv.32 i Baltoy Lv.32. Na piętrze spotkasz Stevena, który poprosi cię o wspólną walkę z Maxiem i Tabithą. Steven używa Metanga Lv.42, Skarmory Lv.43 i Aggrona Lv.44. Maxie ma Mightyena Lv.42 (Swagger, Scary Face, Take Down, Taunt), Crobat Lv.43 (Wing Attack, Confuse Ray, Air Cutter, Mean Look) i Camerupt Lv.44 (Take Down, Amnesia, Rock Slide, Earthquake); Tabitha wspiera go Cameruptem Lv.36, Mightyena Lv.38 i Golbatem Lv.40. Po zwycięstwie plan Team Magma zostaje powstrzymany, a Maxie zaczyna kwestionować własne działania.', location: 'Mossdeep Space Center', pokemon: ['Zubat', 'Poochyena', 'Numel', 'Baltoy', 'Mightyena', 'Metang', 'Skarmory', 'Aggron', 'Crobat', 'Camerupt', 'Golbat']),
  GuideStep(section: 'Seafloor Cavern i ósma odznaka', title: 'Odbierz HM08 Dive od Stevena', description: 'Po obronie Space Center odwiedź Stevena w jego domu na północno-zachodnim krańcu Mossdeep. Otrzymasz HM08 Dive. Na ciemnych, głębokich plamach wody użyj Dive, aby zejść na dno; w miejscach, gdzie promienie światła przebijają się z góry, możesz ponownie użyć Dive, by wypłynąć na powierzchnię. Dive odblokowuje podwodne odcinki Route 124, 127 i 128 oraz dostęp do Seafloor Cavern.', location: 'Mossdeep City — Steven’s House', items: ['HM08 Dive']),
  GuideStep(section: 'Seafloor Cavern i ósma odznaka', title: 'Zbadaj opcjonalną Shoal Cave podczas przypływu i odpływu', description: 'Shoal Cave zmienia układ wraz z pływami: poziom wody zmienia się co sześć godzin, o 3:00 i 9:00. Przy wysokim stanie wody Surfuj do drugiej komory i zbierz cztery Shoal Shells oraz Rare Candy; Big Pearl leży na półce przy wejściu dostępnej z drugiej komory. Przy niskim stanie wody przejdź przez kolejne drabiny do czwartej i trzeciej komory: zbierz cztery Shoal Salts, Ice Heal i Focus Band od Black Belta. W lodowej komorze znajdziesz NeverMeltIce oraz TM07 Hail. Oddaj starcowi cztery Shoal Shells i cztery Shoal Salts, aby otrzymać Shell Bell. Główna jaskinia: Spheal 50%, Zubat 45%, Golbat 5%; Surf: Tentacool 60%, Zubat 30%, Spheal 10%. W lodowej komorze: Spheal 45%, Zubat 40%, Snorunt 10%, Golbat 5%.', location: 'Shoal Cave (opcjonalna)', pokemon: ['Spheal', 'Zubat', 'Golbat', 'Tentacool', 'Snorunt'], encounterRatesPercent: {'Spheal': 50, 'Zubat': 45, 'Golbat': 5}, items: ['Shoal Shell ×4 (przypływ)', 'Shoal Salt ×4 (odpływ)', 'Rare Candy', 'Big Pearl', 'Ice Heal', 'Focus Band', 'NeverMeltIce', 'TM07 Hail', 'Shell Bell']),
  GuideStep(section: 'Seafloor Cavern i ósma odznaka', title: 'Zbadaj Route 124 pod wodą i Abandoned Ship', description: 'Po zdobyciu Dive wróć na Route 124 i sprawdź ciemne punkty. Zbierz Blue Shard, Red Shard i Yellow Shard na powierzchni po wypłynięciu z odpowiednich podwodnych punktów; pod wodą znajdziesz Green Shard, Carbos, dwa Heart Scale, Calcium, Big Pearl i Pearl — część jest ukryta w wodorostach lub przy skałach. Następnie odwiedź Abandoned Ship, które teraz można przejść w całości. W ukrytym piętrze zbierz Room 1 Key, Water Stone, Room 4 Key, TM18 Rain Dance, Room 6 Key, Luxury Ball, Room 2 Key i Scanner. Przekaż Scanner naukowcowi w biurze kapitana, a potem oddaj go Captainowi Sternowi w Slateport Harbor; w zamian wybierzesz DeepSeaTooth albo DeepSeaScale.', location: 'Route 124 / Abandoned Ship / Slateport Harbor', pokemon: ['Magikarp', 'Tentacool', 'Tentacruel'], items: ['Blue Shard', 'Red Shard', 'Yellow Shard', 'Green Shard', 'Carbos', 'Heart Scale ×2', 'Calcium', 'Big Pearl', 'Pearl', 'Room 1 Key', 'Water Stone', 'Room 4 Key', 'TM18 Rain Dance', 'Room 6 Key', 'Luxury Ball', 'Room 2 Key', 'Scanner', 'DeepSeaTooth lub DeepSeaScale']),
  GuideStep(section: 'Seafloor Cavern i ósma odznaka', title: 'Przepłyń Route 127 i Route 128 w drodze do Seafloor Cavern', description: 'Z Mossdeep skieruj się na południe przez Route 127. Pokonaj Bird Keepera Aidana (Swellow i Skarmory Lv.32), Cooltrainer Athenę (Manectric i Linoone Lv.32), Fishermanów Jonaha (Wailmer 30, Tentacool 31, Sharpedo 32), Rogera (dwa Magikarp i Gyarados 35) i Henry’ego (Carvanha 31, Tentacruel 34), Triathlete Camdena (dwa Staryu Lv.33), Black Belta Kojiego (Machoke Lv.34) i Triathlete Donny’ego (Wingull 26, Staryu 34). Aidan i Athena mogą walczyć podwójnie. Route 128: Cooltrainer Ruben (Shiftry i Nosepass Lv.34), Alexa (Gloom i Azumarill Lv.34), Fisherman Wayne (dwa Tentacool 31, Wailmer 36), Triathletes Isaiah i Katelyn (Staryu 35) oraz Swimmers Carlee (Seaking 35) i Harrison (Tentacruel 35). Spotkania Surf na obu trasach: Tentacool 60%, Wingull 35%, Pelipper 5%. Route 127: Super Rod Wailmer 60%, Sharpedo 40%. Route 128: Good Rod Wailmer 20%, Luvdisc 20%, Magikarp 60%; Super Rod Wailmer 45%, Luvdisc 40%, Corsola 15%. Zbierz Zinc, Rare Candy, Carbos, trzy ukryte Heart Scale, Star Piece, HP Up, Red Shard, Protein i Pearl. Na Route 128 użyj Dive w miejscu podwodnej jaskini, a następnie wejdź do Seafloor Cavern.', location: 'Route 127 / Route 128', pokemon: ['Swellow', 'Skarmory', 'Manectric', 'Linoone', 'Wailmer', 'Tentacool', 'Sharpedo', 'Magikarp', 'Gyarados', 'Carvanha', 'Tentacruel', 'Staryu', 'Machoke', 'Wingull', 'Shiftry', 'Nosepass', 'Gloom', 'Azumarill', 'Seaking', 'Pelipper', 'Luvdisc', 'Corsola'], encounterRatesPercent: {'Tentacool': 60, 'Wingull': 35, 'Pelipper': 5}, items: ['Zinc', 'Rare Candy', 'Carbos', 'Heart Scale ×3 (ukryte)', 'Star Piece (ukryty)', 'HP Up (ukryty)', 'Red Shard (ukryty)', 'Protein (ukryty)', 'Pearl (ukryty)']),
  GuideStep(section: 'Seafloor Cavern i ósma odznaka', title: 'Przejdź Seafloor Cavern i pokonaj Shelly', description: 'W jaskini użyj Rock Smash do usunięcia przeszkód i Strength do przesuwania głazów. W pierwszym pokoju przesuń głaz na południe, drugi na wschód; północno-zachodnie przejście prowadzi szybciej do Room 4. W Room 4 oczyść drogę i przesuń zachodni środkowy głaz do północno-zachodniego narożnika. W Room 5 i 6 wykorzystuj prądy wodne, aby dotrzeć do spokojnych zatok i kolejnych drzwi. W Room 7 po zachodniej stronie pokonaj Aqua Admin Shelly: Sharpedo Lv.37 (Scary Face, Crunch, Screech, Slash) i Mightyena Lv.37 (Roar, Swagger, Scary Face, Take Down). W jaskini spotkasz Zubata 90% i Golbata 10%; Surf: Tentacool 60%, Zubat 35%, Golbat 5%.', location: 'Seafloor Cavern — Rooms 1–7', pokemon: ['Zubat', 'Golbat', 'Tentacool', 'Sharpedo', 'Mightyena'], encounterRatesPercent: {'Zubat': 90, 'Golbat': 10}),
  GuideStep(section: 'Seafloor Cavern i ósma odznaka', title: 'Pokonaj Archiego i obudź Kyogre', description: 'W najgłębszej komorze Seafloor Cavern Archie używa Mightyeny Lv.41 (Roar, Swagger, Scary Face, Take Down), Crobat Lv.41 (Bite, Wing Attack, Confuse Ray, Air Cutter) i Sharpedo Lv.43 (Screech, Slash, Taunt, Swagger). Zanim zejdziesz do niego, zbierz TM26 Earthquake na najwyższym poziomie po wschodniej stronie komory. Po zwycięstwie Archie aktywuje Red Orb i budzi Kyogre. To uruchamia kryzys pogodowy — ekstremalne opady i powodzie — a następny cel to Sootopolis City, gdzie Groudon i Kyogre doprowadzą do starcia. Nie próbuj łapać Kyogre w tym momencie; historia poprowadzi cię do rozwiązania konfliktu z udziałem Rayquazy.', location: 'Seafloor Cavern — Deepest Room', pokemon: ['Mightyena', 'Crobat', 'Sharpedo', 'Kyogre'], items: ['TM26 Earthquake', 'Red Orb']),
  GuideStep(section: 'Kryzys pogodowy i Sootopolis', title: 'Dostań się do Sootopolis przez Route 126', description: 'Po opuszczeniu Seafloor Cavern leć lub popłyń do Route 126. Miasto leży wewnątrz ogromnego krateru i nie da się do niego wejść z powierzchni. Zanurkuj w południowej części trasy, odszukaj podwodne przejście w ścianie krateru, a następnie wynurz się wewnątrz Sootopolis. Po drodze możesz spotkać trenerów wodnych; Leonardo i Triathlete Isobel mogą uruchomić Double Battle. W ich drużynach są Carvanha Lv.34 i Staryu Lv.34. Pozostali pływacy używają m.in. Carvanhy, Wingulla, Marill i Spheala.', location: 'Route 126', pokemon: ['Carvanha', 'Staryu', 'Wingull', 'Marill', 'Spheal']),
  GuideStep(section: 'Kryzys pogodowy i Sootopolis', title: 'Zobacz starcie Groudona z Kyogre', description: 'W Sootopolis zobaczysz skutki katastrofy pogodowej: Groudon i Kyogre walczą na środku miasta, a mieszkańcy nie mogą powstrzymać dwóch legendarnych Pokémonów. Nie próbuj teraz szukać walki z liderem Gymu — wejście jest zamknięte. Porozmawiaj z ludźmi i skieruj się do Cave of Origin, aby odnaleźć Wallace’a.', location: 'Sootopolis City', pokemon: ['Groudon', 'Kyogre']),
  GuideStep(section: 'Kryzys pogodowy i Sootopolis', title: 'Przejdź przez Cave of Origin', description: 'Wejdź do jaskini na północy miasta. Na wejściu spotkasz głównie Zubata (90%) i Golbata (10%); na 1F pojawiają się Zubat (60%), Sableye (30%) i Golbat (10%). Przejdź zgodnie z układem korytarzy do drabiny w północno-wschodniej części, a następnie zejdź na B1F. W komorze z rubinami i szafirami nie ma dzikich Pokémonów w miejscu spotkania z Wallace’em.', location: 'Cave of Origin — Entrance / 1F / B1F', pokemon: ['Zubat', 'Golbat', 'Sableye'], encounterRatesPercent: {'Zubat': 60, 'Sableye': 30, 'Golbat': 10}),
  GuideStep(section: 'Kryzys pogodowy i Sootopolis', title: 'Porozmawiaj z Wallace’em i poznaj legendę Rayquazy', description: 'Wallace wyjaśni, że istnieje trzeci pradawny Pokémon — Rayquaza — który według legendy powstrzymał kiedyś Groudona i Kyogre. Wskaż Sky Pillar jako możliwe miejsce jego pobytu. Wallace ruszy tam pierwszy, a ty musisz dotrzeć do wieży od strony Route 131. Pamiętaj: po przebudzeniu Rayquazy wejście do Cave of Origin zostanie zablokowane na resztę gry.', location: 'Cave of Origin — B1F', pokemon: ['Wallace', 'Rayquaza']),
  GuideStep(section: 'Kryzys pogodowy i Sootopolis', title: 'Przepłyń Route 129–131 i dotrzyj do Sky Pillar', description: 'Wyrusz na południowy wschód przez Route 129, 130 i 131. Na Route 129 spotkasz m.in. Swimmera Reeda (Spheal i Sharpedo Lv.33), Triathlete Chase’a (Wingull Lv.26 i Staryu Lv.34), Triathlete Allison (Wingull Lv.27 i Staryu Lv.33), Swimmera Clarence’a (Sharpedo Lv.34) oraz Swimmer Tishę (Chinchou Lv.34); Clarence i Tisha mogą walczyć razem. Surf na Route 129: Tentacool 60%, Wingull 35%, Pelipper 4%, Wailord 1%. Old Rod: Magikarp 70%, Tentacool 30%; Good Rod: Magikarp 60%, Tentacool 20%, Wailmer 20%; Super Rod: Wailmer 60%, Sharpedo 40%.', location: 'Route 129–131', pokemon: ['Tentacool', 'Wingull', 'Pelipper', 'Wailord', 'Magikarp', 'Wailmer', 'Sharpedo', 'Chinchou'], encounterRatesPercent: {'Tentacool': 60, 'Wingull': 35, 'Pelipper': 4, 'Wailord': 1}),
  GuideStep(section: 'Kryzys pogodowy i Sootopolis', title: 'Odwiedź Pacifidlog Town i przygotuj się na prądy oceaniczne', description: 'Pacifidlog jest opcjonalnym przystankiem na trasie przez południowy ocean. Sprawdź domy mieszkańców, codzienne wydarzenia i dostępne rozmowy, a następnie przygotuj drużynę do eksploracji Route 132–134. Silne prądy na tych trasach utrudniają swobodne poruszanie się — kierunek, z którego wpłyniesz na nurt, decyduje o tym, na której wysepce wylądujesz.', location: 'Pacifidlog Town', optional: true),
  GuideStep(section: 'Kryzys pogodowy i Sootopolis', title: 'Zbadaj Route 132, 133 i 134 oraz zdobądź przedmioty', description: 'Przemierzaj trasy oceaniczne kilkoma podejściami, bo prądy rozdzielają wysepki i trenerów. Na Route 132 spotkasz m.in. Swimmerów Gilberta i Danę, Fishermana Ronalda oraz Black Belta Kiyo; Route 133 zawiera kolejne wysepki, a na Route 134 walcz z trenerami w pobliżu płytkich wód. Zbierz Rare Candy i Protein na Route 132, Star Piece i Max Revive na Route 133 oraz Big Pearl i Carbos na Route 134. Warto wrócić do miejsc, do których nie udało się dopłynąć za pierwszym razem.', location: 'Route 132 / Route 133 / Route 134', pokemon: ['Sharpedo', 'Azumarill', 'Magikarp', 'Gyarados'], items: ['Rare Candy', 'Protein', 'Star Piece', 'Max Revive', 'Big Pearl', 'Carbos']),
  GuideStep(section: 'Kryzys pogodowy i Sootopolis', title: 'Otwórz Sealed Chamber i uruchom zagadkę Regis', description: 'Na Route 134 znajdź głęboką wodę otoczoną skałami, zanurkuj i odczytaj zapis Braille’a przy ścianie. Wskaże on miejsce, w którym trzeba wynurzyć się do Sealed Chamber. W pierwszej komorze odczytaj alfabet Braille’a, a przy północnej ścianie użyj Dig, aby otworzyć przejście. W drugiej komnacie ustaw Wailorda na pierwszym miejscu drużyny, a Relicantha na ostatnim i zbadaj północną ścianę. Trzęsienie ziemi otworzy trzy zapieczętowane ruiny.', location: 'Route 134 / Sealed Chamber', pokemon: ['Wailord', 'Relicanth'], items: ['Dig'], optional: true),
  GuideStep(section: 'Kryzys pogodowy i Sootopolis', title: 'Rozwiąż zagadki trzech ruin i złap Regis', description: 'Po otwarciu pieczęci odwiedź Desert Ruins na Route 111 (dwa kroki w lewo, dwa w dół i Rock Smash), Island Cave na Route 105 (obejdź komnatę przy ścianach) oraz Ancient Tomb na Route 120 (stań na środku i użyj Flash). W każdej komnacie czeka legendarny Pokémon na poziomie 40: Regirock, Regice lub Registeel. Przygotuj Ultra Balle/Timer Balle, Pokémon z False Swipe i leczenie statusu; zapis gry przed walką jest rozsądnym zabezpieczeniem.', location: 'Desert Ruins / Island Cave / Ancient Tomb', pokemon: ['Regirock', 'Regice', 'Registeel'], optional: true),
  GuideStep(section: 'Kryzys pogodowy i Sootopolis', title: 'Wejdź do Sky Pillar i dotrzyj na szczyt', description: 'Na północnym krańcu Route 131 znajdź wejście do Sky Pillar. Podczas pierwszej wizyty Wallace otworzy drzwi i wyjaśni, że wieża reaguje na katastrofę pogodową. Na 1F, 3F i 5F występują Golbat (30%), Sableye (30%), Claydol (25%) i Banette (15%); na 5F dodatkowo Altaria (6%), a Claydol spada do 19%. Przejdź do 4F, użyj popękanych płytek, aby spaść na właściwy fragment 3F, a następnie wróć na wyższe piętra i dotrzyj do szczytu.', location: 'Sky Pillar — pierwsza wizyta', pokemon: ['Golbat', 'Sableye', 'Claydol', 'Banette', 'Altaria'], encounterRatesPercent: {'Golbat': 30, 'Sableye': 30, 'Claydol': 25, 'Banette': 15}),
  GuideStep(section: 'Kryzys pogodowy i Sootopolis', title: 'Obudź Rayquazę i wróć do Sootopolis', description: 'Na szczycie podejdź do Rayquazy. Smok obudzi się i poleci do Sootopolis, gdzie rozdzieli Groudona i Kyogre, kończąc katastrofalny konflikt. Wróć do miasta i obejrzyj scenę z udziałem Wallace’a, Stevena, Archiego i Maxiego. Liderzy Team Aqua i Team Magma zrozumieją swój błąd i odniosą Blue Orb oraz Red Orb na Mt. Pyre.', location: 'Sky Pillar / Sootopolis City', pokemon: ['Rayquaza', 'Groudon', 'Kyogre']),
  GuideStep(section: 'Kryzys pogodowy i Sootopolis', title: 'Odbierz HM07 Waterfall i przygotuj się do Gymu', description: 'Po zakończeniu sceny Wallace podziękuje ci i wręczy HM07 Waterfall. Zanim ruszysz do Gymu, możesz odebrać TM31 Brick Break od Black Belta w północno-zachodnim domu, Wailmer Doll od dziewczyny w domu na wschód od Pokémon Center oraz dwa Elixiry za pokazanie odpowiednio dużego Seedota i Lotada braciom w domu na północnym wschodzie. Jednorazowa Move Tutor w Pokémon Center może nauczyć wybranego Pokémona Double-Edge.', location: 'Sootopolis City', items: ['HM07 Waterfall', 'TM31 Brick Break', 'Wailmer Doll', 'Elixir ×2', 'Double-Edge']),
  GuideStep(section: 'Ósma odznaka — Sootopolis Gym', title: 'Rozwiąż lodową zagadkę Sootopolis Gym', description: 'Liderem Gymu w Emerald jest Juan, nie Wallace. Podłoga ma trzy poziomy lodowych pól; każde pole trzeba nadepnąć dokładnie raz. Drugie przejście po tym samym polu rozbije lód i zrzuci cię na niższy poziom, gdzie czekają trenerzy. Pierwsza plansza ma siatkę 3×3, druga 7×3, a ostatnia 11×4. Jeśli spadniesz, pokonaj trenerów na dolnym piętrze i ponów próbę. Grass i Electric są najlepsze przeciw większości drużyny Juana.', location: 'Sootopolis Gym', pokemon: ['Luvdisc', 'Whiscash', 'Sealeo', 'Crawdaunt', 'Kingdra']),
  GuideStep(section: 'Ósma odznaka — Sootopolis Gym', title: 'Pokonaj trenerów Gymu i Juana', description: 'Trenerzy używają m.in. Goldeen Lv.40, Luvdisc Lv.40, Feebas Lv.39, Carvanha i Sharpedo Lv.39, Azurill Lv.35, Marill Lv.37, Azumarill Lv.39, Clamperl Lv.35, Corphish Lv.37, Lombre Lv.39, Seaking Lv.40 i Wailmer Lv.39. Juan: Luvdisc Lv.41 (Water Pulse, Attract, Sweet Kiss, Flail), Whiscash Lv.41 (Rain Dance, Water Pulse, Amnesia, Earthquake), Sealeo Lv.43 (Encore, Body Slam, Aurora Beam, Water Pulse), Crawdaunt Lv.43 (Water Pulse, Crabhammer, Taunt, Leer) i Kingdra Lv.46 (Water Pulse, Double Team, Ice Beam, Rest; Chesto Berry). Whiscash jest odporny na Electric, więc pokonaj go ruchem Grass. Kingdra nie ma typowej słabości do Electric/Grass — przyda się Dragon lub mocny neutralny atak. Po zwycięstwie dostaniesz Rain Badge i TM03 Water Pulse.', location: 'Sootopolis Gym', pokemon: ['Luvdisc', 'Whiscash', 'Sealeo', 'Crawdaunt', 'Kingdra'], items: ['Rain Badge', 'TM03 Water Pulse']),
  GuideStep(section: 'Droga do Pokémon League', title: 'Dostań się do Ever Grande City', description: 'Mając osiem odznak, popłyń na południe od Mossdeep i dalej na wschód przez wąski kanał Route 128. Użyj Waterfall przy południowej części Ever Grande, aby wspiąć się do północnego wejścia miasta. W południowej części możesz złowić Magikarp, Tentacool, Wailmer, Luvdisc lub Corsolę zależnie od użytej wędki; Surf daje Tentacool 60%, Wingull 35% i Pelipper 5%. Wylecz drużynę w Pokémon Center i porozmawiaj ze Scottem przed wejściem do Victory Road.', location: 'Route 128 / Ever Grande City', pokemon: ['Tentacool', 'Wingull', 'Pelipper', 'Magikarp', 'Wailmer', 'Luvdisc', 'Corsola'], encounterRatesPercent: {'Tentacool': 60, 'Wingull': 35, 'Pelipper': 5}),
  GuideStep(section: 'Droga do Pokémon League', title: 'Przejdź Victory Road — piętra i trenerzy', description: 'Victory Road wymaga Surf, Strength, Rock Smash i Waterfall; Flash jest opcjonalny, ale pomaga na B1F. Pokonaj trenerów: Albert (Magneton i Muk Lv.43), Hope (Roselia Lv.45), Shannon (Claydol Lv.45), Samuel (Swellow, Mawile i Kadabra Lv.42), Julie (Sandslash, Ninetales i Tropius Lv.42), Owen (Kecleon, Graveler i Wailord Lv.42), Dianne (Claydol i Lanturn Lv.43), Felix (Medicham i Claydol Lv.43), Caroline (Skarmory i Sableye Lv.43), Vito (Dodrio, Kadabra, Electrode i Shiftry Lv.42) oraz Michelle (Torkoal, Medicham i Ludicolo Lv.42). Używaj Strength do przesuwania głazów i Rock Smash do kruszenia pękniętych skał; odnogi kryją przedmioty, więc nie biegnij wyłącznie głównym korytarzem.', location: 'Victory Road — 1F / B1F / B2F', pokemon: ['Magneton', 'Muk', 'Roselia', 'Claydol', 'Swellow', 'Mawile', 'Kadabra', 'Sandslash', 'Ninetales', 'Tropius', 'Kecleon', 'Graveler', 'Wailord', 'Lanturn', 'Medicham', 'Skarmory', 'Sableye', 'Dodrio', 'Electrode', 'Shiftry', 'Torkoal', 'Ludicolo'], items: ['PP Up', 'Ultra Ball']),
  GuideStep(section: 'Droga do Pokémon League', title: 'Pokonaj Wally’ego w Victory Road', description: 'Wally czeka w głębi Victory Road i ma drużynę na poziomach 43–45: Altaria Lv.44 (Aerial Ace, Safeguard, DragonBreath, Dragon Dance), Delcatty Lv.43, Roselia Lv.44, Magneton Lv.41, oraz Gardevoir Lv.45. Altarię najlepiej zaatakować ruchem Ice, Magnetona ruchem Ground, a Roselię Fire, Ice, Flying lub Psychic. Uważaj na Dragon Dance Altarii, Toxic i Leech Seed Roselii oraz Calm Mind Gardevoir. Po walce Wally zostanie w Victory Road i po Hall of Fame będzie można do niego wrócić.', location: 'Victory Road', pokemon: ['Altaria', 'Delcatty', 'Roselia', 'Magneton', 'Gardevoir']),
  GuideStep(section: 'Droga do Pokémon League', title: 'Przygotuj drużynę do Pokémon League', description: 'Przed wejściem do ligi kup Hyper Potions, Full Restores, Full Heals i Revive. Pięć walk odbywa się jedna po drugiej — nie możesz wrócić do Pokémon Center pomiędzy członkami Elite Four i Championem. Zapisz grę przed wejściem do ostatniej sali, bo po pokonaniu Drake’a walka z Championem rozpoczyna się od razu. Dobrym celem jest drużyna na poziomach około 50–58 z odpowiedziami na Dark, Ghost, Ice, Dragon i Water.', location: 'Pokémon League', items: ['Hyper Potion', 'Full Restore', 'Full Heal', 'Revive']),
  GuideStep(section: 'Pokémon League', title: 'Pokonaj Sidney’a — pierwszego członka Elite Four', description: 'Sidney używa: Mightyena Lv.46 (Roar, Double-Edge, Sand-Attack, Crunch), Shiftry Lv.48 (Torment, Double Team, Swagger, Extrasensory), Cacturne Lv.46 (Leech Seed, Faint Attack, Needle Arm, Cotton Spore), Crawdaunt Lv.48 (Surf, Swords Dance, Strength, Facade) i Absol Lv.49 (Aerial Ace, Rock Slide, Swords Dance, Slash; Sitrus Berry). Typ Fighting i Bug jest skuteczny, ale pamiętaj, że Psychic nie działa na Dark. Intimidate Mightyeny obniża Attack, więc możesz użyć ataków specjalnych.', location: 'Pokémon League — Sidney', pokemon: ['Mightyena', 'Shiftry', 'Cacturne', 'Crawdaunt', 'Absol']),
  GuideStep(section: 'Pokémon League', title: 'Pokonaj Phoebe — drugą członkinię Elite Four', description: 'Phoebe używa: Dusclops Lv.48 (Shadow Punch, Confuse Ray, Curse, Protect), Banette Lv.49 (Shadow Ball, Grudge, Will-O-Wisp, Faint Attack), Sableye Lv.50 (Shadow Ball, Double Team, Night Shade, Faint Attack), drugiego Banette Lv.49 (Shadow Ball, Psychic, Thunderbolt, Facade) i Dusclopsa Lv.51 (Shadow Ball, Ice Beam, Rock Slide, Earthquake; Sitrus Berry). Najlepsze są ruchy Dark i Ghost. Uważaj na Curse, Will-O-Wisp, Confuse Ray i Pressure, które szybko zużywa PP.', location: 'Pokémon League — Phoebe', pokemon: ['Dusclops', 'Banette', 'Sableye']),
  GuideStep(section: 'Pokémon League', title: 'Pokonaj Glacię — trzecią członkinię Elite Four', description: 'Glacia używa: Sealeo Lv.50 (Encore, Body Slam, Hail, Ice Ball), Glalie Lv.50 (Light Screen, Crunch, Icy Wind, Ice Beam), Sealeo Lv.52 (Attract, Double-Edge, Hail, Blizzard), Glalie Lv.52 (Shadow Ball, Explosion, Hail, Ice Beam) i Walrein Lv.53 (Surf, Body Slam, Ice Beam, Sheer Cold; Sitrus Berry). Fighting, Rock, Electric i Fire pomagają na jej mieszany zespół Ice/Water. Nie lekceważ Sheer Cold Walreina ani Explosion Glalie.', location: 'Pokémon League — Glacia', pokemon: ['Sealeo', 'Glalie', 'Walrein']),
  GuideStep(section: 'Pokémon League', title: 'Pokonaj Drake’a — czwartego członka Elite Four', description: 'Drake używa: Shelgon Lv.52 (Rock Tomb, Dragon Claw, Protect, Double-Edge), Altaria Lv.54 (Double-Edge, DragonBreath, Dragon Dance, Aerial Ace), Kingdra Lv.53 (SmokeScreen, Dragon Dance, Surf, Body Slam), Flygon Lv.53 (Flamethrower, Crunch, DragonBreath, Earthquake) i Salamence Lv.55 (Flamethrower, Dragon Claw, Rock Slide, Crunch; Sitrus Berry). Ice jest bardzo skuteczne na większość drużyny, ale Kingdra nie ma słabości do Ice. Uważaj na Dragon Dance Altarii i Kingdry oraz Intimidate Salamence’a.', location: 'Pokémon League — Drake', pokemon: ['Shelgon', 'Altaria', 'Kingdra', 'Flygon', 'Salamence']),
  GuideStep(section: 'Pokémon League', title: 'Pokonaj Championa Wallace’a i wejdź do Hall of Fame', description: 'Champion Wallace używa: Wailord Lv.57 (Rain Dance, Water Spout, Double-Edge, Blizzard), Tentacruel Lv.55 (Toxic, Hydro Pump, Sludge Bomb, Ice Beam), Ludicolo Lv.56 (Giga Drain, Surf, Leech Seed, Double Team), Whiscash Lv.56 (Earthquake, Surf, Amnesia, Hyper Beam), Gyarados Lv.56 (Dragon Dance, Earthquake, Hyper Beam, Surf) i Milotic Lv.58 (Recover, Surf, Ice Beam, Toxic; Sitrus Berry). Grass i Electric są przydatne, ale Whiscash wymaga Grass, a Gyarados może odpowiedzieć Earthquake na Electric. Milotic ma Recover i Toxic — nie pozwól mu przeciągać walki. Po zwycięstwie obejrzysz ceremonię Hall of Fame i ukończysz główną historię.', location: 'Pokémon League — Champion Wallace', pokemon: ['Wailord', 'Tentacruel', 'Ludicolo', 'Whiscash', 'Gyarados', 'Milotic']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Odbierz S.S. Ticket i wybierz wędrującego Pokémona', description: 'Po napisach obudzisz się w Littleroot Town. Norman przekaże ci S.S. Ticket. W telewizyjnym raporcie zobaczysz informację o Eon Pokémonie; odpowiedź czerwona oznacza Latias, a niebieska Latiosa. Wybrany Pokémon zacznie wędrować po Hoenn.', location: 'Littleroot Town', pokemon: ['Latias', 'Latios'], items: ['S.S. Ticket']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Odblokuj podróż S.S. Tidal', description: 'Po napisach końcowych obudzisz się w Littleroot Town. Norman wręczy ci S.S. Ticket od Mr. Brineya. Poleć do Slateport lub Lilycove i pokaż bilet pracownicy portu, aby wybrać rejs. Na statku Scott zaprosi cię do Battle Frontier i uzgodni z kapitanem możliwość podróży na wyspę. Na 1F możesz odpocząć we własnej kabinie (druga od lewej po południowej stronie), walczyć z trenerami w pozostałych kabinach i odebrać TM49 Snatch w północno-wschodniej kabinie. W piwnicy pokonaj dwóch Sailorów i przeszukaj północno-zachodni kosz — znajdziesz ukryte Leftovers. Po dopłynięciu wysiądź i wejdź na statek ponownie, aby wybrać Battle Frontier.', location: 'Littleroot Town / Slateport City / Lilycove City / S.S. Tidal', items: ['S.S. Ticket', 'TM49 Snatch', 'Leftovers'], pokemon: ['Luvdisc', 'Azumarill', 'Manectric', 'Skitty', 'Machop', 'Pelipper', 'Machoke']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Odbierz Frontier Pass i sprawdź dom Scotta', description: 'Po pierwszym wejściu do Battle Frontier odbierz Frontier Pass przy bramie. Zapisuje on Battle Points, symbole i rekordy. Odwiedź Scotta w domu między Battle Dome i Battle Tower — może przyznać początkowe BP zależnie od wcześniejszych rozmów.', location: 'Battle Frontier — wejście / Scott’s House', items: ['Frontier Pass', 'Battle Points']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Battle Factory — zdobądź Knowledge Symbol', description: 'Wybierz 3 z 6 losowych Pokémonów wypożyczonych na początku wyzwania. Po każdej wygranej możesz wymienić jednego ze swoich Pokémonów na jednego z drużyny pokonanego trenera, ale przed wymianą nie poznasz jego statystyk. Każda runda składa się z 7 walk. Noland pojawia się w 21. walce (po 3 rundach) po srebrny Knowledge Symbol oraz w 42. walce (po 6 rundach) po złoty. Jego drużyna jest losowana z puli Pokémonów Factory — nie zakładaj, że spotkasz zawsze ten sam skład.', location: 'Battle Factory', items: ['Silver Knowledge Symbol', 'Gold Knowledge Symbol']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Battle Dome — zdobądź Tactics Symbol', description: 'Turniej ma drabinkę 16 trenerów. Przed każdym pojedynkiem poznajesz krótką charakterystykę rywala, a do walki wybierasz 2 Pokémony z własnej trójki. Nie musisz wygrać wszystkich 16 walk: jedno mistrzostwo turnieju oznacza cztery zwycięstwa. Tucker czeka po zdobyciu 5. tytułu mistrzowskiego (srebrny Tactics Symbol; 19 łącznych walk turniejowych) oraz po 10. tytule (złoty; 39 łącznych walk). Srebrny skład Tuckera: Swampert, Salamence i Charizard; złoty: Swampert, Metagross i Latias. Zmieniaj kolejność dwóch wybranych Pokémonów pod przewidywanego przeciwnika.', location: 'Battle Dome', pokemon: ['Swampert', 'Salamence', 'Charizard', 'Metagross', 'Latias'],  items: ['Silver Tactics Symbol', 'Gold Tactics Symbol']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Battle Pike — zdobądź Luck Symbol', description: 'Każdy etap składa się z 3 kolejnych pomieszczeń; przed wejściem wybierasz jedną z trzech ścieżek. W środku możesz trafić na walkę, leczenie, status, dzikiego Pokémona albo losowe zdarzenie — rozpoznawaj wskazówki personelu, ale nie zakładaj, że są gwarancją. Lucy pojawia się po ukończeniu 2 pełnych przejść przez 21-pokojowy obiekt (srebrny Luck Symbol) oraz po 10 pełnych przejściach (złoty). Wskazówki kobiety przed pokojami mogą pomóc wybrać ścieżkę, ale zdarzenia obejmują walki, dzikie Pokémony, leczenie, statusy i puste pokoje. Jej drużyny: srebrna — Seviper, Shuckle, Milotic; złota — Seviper, Steelix, Gyarados. Po walce wróć do recepcji i sprawdź zapis symbolu na Frontier Pass.', location: 'Battle Pike', pokemon: ['Seviper', 'Shuckle', 'Milotic', 'Steelix', 'Gyarados'],  items: ['Silver Luck Symbol', 'Gold Luck Symbol']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Battle Tower — zdobądź Ability Symbol', description: 'Wybierz format Single (3 Pokémony), Double (4 Pokémony) albo Multi. W klasycznym wyzwaniu Single seria składa się z grup po 7 walk. Anabel pojawia się w 35. walce po srebrny Ability Symbol oraz w 70. walce po złoty — to nie jest próg 5 i 10 rund. Srebrna drużyna Anabel: Alakazam, Entei i Snorlax; złota: Raikou, Latios i Snorlax. Buduj zespół z dobrą synergią typów, odpornościami i różnymi rolami; po każdej serii możesz zmienić skład i przedmioty.', location: 'Battle Tower', pokemon: ['Alakazam', 'Entei', 'Snorlax', 'Raikou', 'Latios'],  items: ['Silver Ability Symbol', 'Gold Ability Symbol']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Battle Arena — zdobądź Guts Symbol', description: 'Każda walka trwa maksymalnie 3 tury. Jeśli po trzeciej turze obaj Pokémoni nadal stoją, sędziowie oceniają Mind (nastawienie ofensywne), Skill (skuteczność ruchów) i Body (pozostałe HP oraz stan). Greta pojawia się w 28. walce po srebrny Guts Symbol i w 56. po złoty. Srebrny skład: Heracross (Megahorn, Rock Tomb, Endure, Reversal), Umbreon (Body Slam, Confuse Ray, Psychic, Faint Attack), Shedinja (Shadow Ball, Return, Confuse Ray, Aerial Ace). Złoty skład: Umbreon (Double-Edge, Confuse Ray, Rest, Psychic), Gengar (Psychic, Hypnosis, Dream Eater, Destiny Bond), Breloom (Spore, Focus Punch, Giga Drain, Headbutt).', location: 'Battle Arena', pokemon: ['Heracross', 'Umbreon', 'Shedinja', 'Gengar', 'Breloom'], items: ['Silver Guts Symbol', 'Gold Guts Symbol']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Battle Palace — zdobądź Spirits Symbol', description: 'Nie wybierasz ruchu w turze — Pokémon sam decyduje, czy użyje ataku, ruchu obronnego czy wspierającego. Decyzje zależą od natury oraz aktualnego HP. Spenser pojawia się w 21. walce po srebrny Spirits Symbol i w 42. po złoty. Srebrny skład: Crobat (Confuse Ray, Double Team, Toxic, Fly), Slaking (Earthquake, Swagger, Shadow Ball, Brick Break), Lapras (Ice Beam, Horn Drill, Confuse Ray, Protect). Złoty skład: Arcanine (Overheat, ExtremeSpeed, Roar, Protect), Slaking (Hyper Beam, Earthquake, Shadow Ball, Yawn), Suicune (Blizzard, Surf, Bite, Calm Mind).', location: 'Battle Palace', pokemon: ['Crobat', 'Slaking', 'Lapras', 'Arcanine', 'Suicune'], items: ['Silver Spirits Symbol', 'Gold Spirits Symbol']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Battle Pyramid — zdobądź Brave Symbol', description: 'Wspinaj się przez siedmiopiętrowe wyprawy w ciemności. Przedmioty znalezione na piętrach trafiają do Battle Bag, a poziomy mapy, trenerzy i przedmioty zmieniają się między wyprawami. Brandon pojawia się na 21. piętrze po srebrny Brave Symbol i na 70. piętrze po złoty. Srebrny skład: Regirock (Explosion, Superpower, Earthquake, AncientPower), Registeel (Earthquake, Metal Claw, Toxic, Iron Defense), Regice (Ice Beam, Amnesia, Thunder, Rest). Złoty skład: Articuno (Blizzard, Water Pulse, Aerial Ace, Reflect), Zapdos (Thunder, Detect, Drill Peck, Light Screen), Moltres (Fire Blast, Hyper Beam, Aerial Ace, Safeguard).', location: 'Battle Pyramid', pokemon: ['Regirock', 'Registeel', 'Regice', 'Articuno', 'Zapdos', 'Moltres'], items: ['Silver Brave Symbol', 'Gold Brave Symbol']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Battle Points — jak zdobywać i planować nagrody', description: 'Każda ukończona próba daje BP, a liczba punktów rośnie wraz z kolejnymi wygranymi wyzwaniami i ma limit zależny od obiektu. Za pokonanie Frontier Brain otrzymasz dodatkowe 10 BP. Orientacyjne maksymalne wypłaty za pojedyncze ukończone wyzwanie w trybie Single: Tower 15 BP, Dome 13 BP, Palace 15 BP, Arena 15 BP, Factory 15 BP, Pike 14 BP i Pyramid 15 BP. Zapisuj saldo na Frontier Pass i planuj zakupy przed rozpoczęciem długiej serii.', location: 'Battle Frontier — wszystkie obiekty', items: ['Battle Points']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Wydawaj BP w Exchange Service Corner', description: 'Punkt wymiany znajduje się przed Battle Tower. W kiosku z przedmiotami trzymanymi kupisz Leftovers, White Herb, Quick Claw i Mental Herb po 48 BP; BrightPowder, Choice Band, King’s Rock, Focus Band i Scope Lens kosztują po 64 BP. Kiosk z witaminami sprzedaje HP Up, Protein, Iron, Calcium, Zinc i Carbos po 1 BP. Pozostałe stanowiska oferują dekoracje do Secret Base — od małych ozdób po duże lalki Pokémonów. Jeśli przygotowujesz drużynę do trudnych serii, najpierw rozważ przedmioty trzymane, a dopiero potem dekoracje.', location: 'Battle Frontier — Exchange Service Corner', items: ['Leftovers', 'White Herb', 'Quick Claw', 'Mental Herb', 'BrightPowder', 'Choice Band', 'King’s Rock', 'Focus Band', 'Scope Lens']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Poznaj zasady poziomów i ograniczenia Battle Frontier', description: 'Przed rozpoczęciem wyzwania wybierz Level 50 albo Open Level. W Level 50 Pokémony powyżej poziomu 50 są niedozwolone; w Open Level każdy Pokémon musi mieć co najmniej poziom 60, a przeciwnicy skalują się do najwyższego poziomu twojej drużyny. W obiektach Frontier nie wolno używać dwóch takich samych trzymanych przedmiotów ani przedmiotów z normalnej torby podczas walki (wyjątkiem jest Battle Pyramid). Walki nie dają doświadczenia ani pieniędzy. Nie można wystawić m.in. Mew, Mewtwo, Lugii, Ho-Oh, Celebi, Kyogre, Groudona, Rayquazy, Jirachiego, Deoxysa ani jajka. Frontier Brain pojawia się wyłącznie w trybie Single 3 na 3 — wygrane w Double lub Multi nie zaliczają serii potrzebnej do symbolu.', location: 'Battle Frontier — recepcja', optional: true),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Złap Sudowoodo przy Battle Frontier', description: 'Na ścieżce w pobliżu Battle Palace stoi poruszające się drzewo. Użyj na nim Wailmer Pail, aby rozpocząć walkę z Sudowoodo na poziomie 40. To pojedyncze spotkanie — zapisz grę przed użyciem konewki, osłab go ostrożnie i spróbuj złapać. Po złapaniu lub pokonaniu odblokujesz przejście do wodospadu i Artisan Cave.', location: 'Battle Frontier — ścieżka przy Battle Palace', pokemon: ['Sudowoodo'], items: ['Wailmer Pail'], optional: true),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Zbadaj Artisan Cave i złap Smeargle', description: 'Po usunięciu Sudowoodo użyj Surf i Waterfall, aby dostać się do Artisan Cave. W jaskini spotkasz Smeargle; to dobre miejsce do zdobycia kolejnego egzemplarza i eksperymentowania ze Sketch. Sprawdź obie kondygnacje oraz boczne odnogi, a przed wyjściem zbierz przedmioty leżące na ziemi. Smeargle może nauczyć się niemal dowolnego ruchu, jeśli użyje Sketch na odpowiednim celu.', location: 'Artisan Cave', pokemon: ['Smeargle'], optional: true),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Naucz Pokémony ruchów u Frontier Move Tutors', description: 'W budynku na południowy zachód od Battle Dome znajdziesz dwie Move Tutors, które uczą po 10 ruchów za BP. Pierwsza: Softboiled (16), Seismic Toss (24), Dream Eater (24), Mega Punch (24), Mega Kick (48), Body Slam (48), Rock Slide (48), Counter (48), Thunder Wave (48) i Swords Dance (48). Druga: Defense Curl (16), Snore (24), Mud-Slap (24), Swift (24), Icy Wind (24), Endure (48), Psych Up (48), Ice Punch (48), ThunderPunch (48) i Fire Punch (48). Zanim wydasz BP, sprawdź, czy dany Pokémon może nauczyć się wybranego ruchu.', location: 'Battle Frontier — Move Tutor House', items: ['Battle Points'], optional: true),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Sprawdź IV Pokémonów u Stats Judge’a', description: 'W budynku za Pokémon Center mieszka Stats Judge. Pokaż mu Pokémona, a oceni sumę jego sześciu IV, a następnie wskaże statystykę z najwyższą wartością i przedział jej IV. Jeśli kilka statystyk ma taki sam najwyższy IV, może wymienić więcej niż jedną. To przydatne narzędzie do selekcji Pokémonów przed długimi seriami Battle Frontier.', location: 'Battle Frontier — dom za Pokémon Center', pokemon: ['Pokémony z wysokimi IV'], optional: true),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Wymień Skitty na Meowtha', description: 'W małym domu na zachód od Battle Tower porozmawiaj z kobietą, która chce wymienić swojego Meowtha na Skitty. Skitty możesz złapać na Route 116. Meowth nie występuje normalnie na wolności w Emerald, więc wymiana jest jedynym lokalnym sposobem zdobycia tego gatunku bez transferu. Otrzymany Meowth trzyma Retro Mail.', location: 'Battle Frontier — dom wymiany', pokemon: ['Skitty', 'Meowth'], items: ['Retro Mail'], optional: true),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Sprawdzaj Ranking Hall i zakłady Double or Nothing', description: 'Ranking Hall na północy wyspy pokazuje rekordy trzech grup obiektów: Factory, Dome i Pike w zachodniej sali, Tower w środkowej oraz Arena, Palace i Pyramid we wschodniej. Po zdobyciu trzech srebrnych symboli odblokuje się zakład Double or Nothing w budynku na południe od Battle Pyramid. Wybierasz dzienny cel i stawkę 5, 10 albo 15 BP; sukces zwraca podwójną stawkę, porażka ją zabiera.', location: 'Battle Frontier — Ranking Hall / Double or Nothing', items: ['Battle Points'], optional: true),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Zdobądź osłony Battle Tower za długie serie', description: 'Poza symbolami Frontier Brain możesz zdobyć dwa dodatkowe trofea. Wygraj 50 kolejnych walk w Battle Tower, aby Scott wręczył Silver Shield; za 100 kolejnych zwycięstw otrzymasz Gold Shield. To osobny cel — nie zastępuje zdobywania symboli i wymaga utrzymania ciągłej serii w Battle Tower.', location: 'Battle Tower / Scott’s House', items: ['Silver Shield', 'Gold Shield'], optional: true),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Zdobądź wszystkie srebrne symbole', description: 'Pokonaj każdego z siedmiu Frontier Brains po raz pierwszy. Każde pierwsze zwycięstwo daje srebrny symbol odpowiedniego obiektu oraz 10 BP. Scott nagradza komplet siedmiu srebrnych symboli Lansat Berry.', location: 'Battle Frontier', items: ['7 Silver Frontier Symbols', 'Lansat Berry']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Zdobądź wszystkie złote symbole', description: 'Pokonaj ponownie wszystkich siedmiu Frontier Brains. Drugie zwycięstwo nad każdym z nich daje złoty symbol i 10 BP. Za komplet siedmiu złotych symboli Scott wręcza Starf Berry.', location: 'Battle Frontier', items: ['7 Gold Frontier Symbols', 'Starf Berry']),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Ukończ dodatkowe wyzwanie Battle Tower', description: 'Niezależnie od symboli Frontier Brain wygraj 50 kolejnych walk w Battle Tower, aby otrzymać Silver Shield od Scotta. Za 100 kolejnych zwycięstw otrzymasz Gold Shield.', location: 'Battle Tower / Scott’s House', items: ['Silver Shield', 'Gold Shield'], optional: true),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Zbadaj pozostałe atrakcje Battle Frontier', description: 'Po pokonaniu Sudowoodo użyj Wailmer Pail, aby je obudzić. Następnie zbadaj Artisan Cave, gdzie można spotkać Smeargle, Ranking Hall, wymianę Skitty na Meowth, Trainer Hill, Move Tutors i Exchange Service Corner. Wydawaj BP rozważnie — część tutorów i przedmiotów kosztuje ich sporo.', location: 'Battle Frontier', pokemon: ['Sudowoodo', 'Smeargle', 'Meowth'], items: ['Wailmer Pail', 'Battle Points'], optional: true),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Odbierz Belduma z domu Stevena', description: 'Po Hall of Fame odwiedź dom Stevena w Mossdeep City. Przeczytaj notatkę na stole i odbierz Poké Ball z Beldumem na poziomie 5.', location: 'Mossdeep City — dom Stevena', pokemon: ['Beldum'], optional: true),
  GuideStep(section: 'Post-game i Battle Frontier', title: 'Pokonaj Stevena w Meteor Falls', description: 'Po wejściu do Hall of Fame odblokuje się górna część Meteor Falls. Wróć do Meteor Falls i użyj Surf oraz Waterfall, aby dostać się do górnej komnaty. Steven ma sześć Pokémonów: Skarmory Lv.77 (Toxic, Aerial Ace, Spikes, Steel Wing), Claydol Lv.75 (Reflect, Light Screen, AncientPower, Earthquake), Aggron Lv.76 (Thunder, Earthquake, SolarBeam, Dragon Claw), Cradily Lv.76 (Giga Drain, AncientPower, Ingrain, Confuse Ray), Armaldo Lv.76 (Water Pulse, AncientPower, Aerial Ace, Slash) i Metagross Lv.78 (Earthquake, Psychic, Meteor Mash, Shadow Ball; Sitrus Berry). Zabierz mocne ruchy Water, Ground, Fighting i Fire. Zapisz grę przed rozmową — to jednorazowa walka.', location: 'Meteor Falls — upper room', pokemon: ['Skarmory', 'Claydol', 'Aggron', 'Cradily', 'Armaldo', 'Metagross'], optional: true),
  GuideStep(section: 'Legendarne Pokémony', title: 'Złap Rayquazę', description: 'Po zostaniu Championem wróć na szczyt Sky Pillar. Tym razem popękane płytki na 2F i 4F wymagają Mach Bike — rozpędź się i nie zatrzymuj na pękniętych polach. Rayquaza czeka na poziomie 70, ma Ability Air Lock i zna Fly, Rest, Outrage oraz Extremespeed. Przygotuj Pokémony odporne na Dragon/Flying, ruchy osłabiające bez nokautowania oraz dużo Ultra Ball i Timer Ball. Uważaj na Rest, który leczy Rayquazę i usuwa status. Zapisz grę przed rozpoczęciem spotkania.', location: 'Sky Pillar — summit', pokemon: ['Rayquaza'], items: ['Ultra Ball', 'Timer Ball'], optional: true),
  GuideStep(section: 'Legendarne Pokémony', title: 'Znajdź Groudon w Terra Cave', description: 'Po ukończeniu ligi wróć do Weather Institute na Route 119 i porozmawiaj z meteorologiem na 2F. Jeśli zgłosi silną suszę, Terra Cave pojawi się na jednej z tras 114, 115, 116 lub 118. Lokalizacja zmienia się, gdy opuścisz instytut, więc sprawdź wskazaną trasę od razu; na Route 114 do wejścia trzeba dostać się przez Waterfall. W drugiej komorze czeka Groudon Lv.70 z Drought i ruchami Fire Blast, Rest, Fissure oraz SolarBeam. Zapisz grę przed walką — jeśli go pokonasz, jaskinia zniknie i przeniesie się w inne miejsce.', location: 'Weather Institute / Terra Cave', pokemon: ['Groudon'], optional: true),
  GuideStep(section: 'Legendarne Pokémony', title: 'Otwórz ruiny Regi', description: 'Zdobądź Relicantha i Wailorda, a następnie rozwiąż zagadkę w Sealed Chamber. Wymagany jest także Dig.', location: 'Route 134 / Sealed Chamber', pokemon: ['Relicanth', 'Wailord'], items: ['Dig'], optional: true),
  GuideStep(section: 'Legendarne Pokémony', title: 'Złap Regirocka, Regice i Registeela', description: 'Po otwarciu ruin odwiedź Desert Ruins, Island Cave i Ancient Tomb. Każda ruina ma osobną zagadkę środowiskową.', location: 'Desert Ruins / Island Cave / Ancient Tomb', pokemon: ['Regirock', 'Regice', 'Registeel'], optional: true),
  GuideStep(section: 'Legendarne Pokémony', title: 'Złap wędrującego Latiasa albo Latiosa', description: 'Po pierwszych napisach w domu w Littleroot Town telewizja pokaże wiadomość o Pokémonie latającym nad Hoenn. Mama zapyta, czy był czerwony czy niebieski: czerwony oznacza Latiasa, niebieski — Latiosa. Wybrany Pokémon wędruje po trawach i trasach Hoenn na poziomie 40; po pierwszym spotkaniu Pokédex pokazuje jego aktualną lokalizację. Zwykle ucieka już w pierwszej turze, dlatego użyj Wobbuffeta z Shadow Tag albo szybkiego Pokémona z Mean Look. Jeśli nałożysz status, pozostanie on po ucieczce i przy kolejnym spotkaniu. Nie myl wędrującego Eon Pokémona z drugim, którego można spotkać na Southern Island po zdobyciu Eon Ticket.', location: 'Hoenn — losowe trasy', pokemon: ['Latias', 'Latios'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Odbierz National Pokédex', description: 'Po wejściu do Hall of Fame odwiedź laboratorium Profesora Bircha. Otrzymasz National Pokédex, który rozszerza rejestr o gatunki spoza regionalnego Hoenn Dex.', location: 'Littleroot Town — Professor Birch’s Lab', items: ['National Pokédex'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Zdobądź startera z Johto', description: 'Złap wszystkie 200 Pokémonów z regionalnego Hoenn Pokédexu i wróć do Profesora Bircha. W nagrodę wybierzesz jednego startera z Johto: Chikorita, Cyndaquil albo Totodile.', location: 'Littleroot Town — Professor Birch’s Lab', pokemon: ['Chikorita', 'Cyndaquil', 'Totodile'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Odblokuj rewanże z liderami Gymów i Wallym', description: 'Po wejściu do Hall of Fame i otrzymaniu National Pokédexu liderzy Gymów mogą zgłaszać gotowość do rewanżu przez Match Call w PokéNav. Każdy rewanż jest Double Battle, a każdy lider ma cztery coraz silniejsze składy. Gotowość może zostać wylosowana po co 60. spotkaniu z dzikim Pokémonem, co 20. walce z trenerem lub co 20. walce w Battle Frontier — szansa wynosi 31%. Musisz pokonać wszystkich liderów na danym poziomie, zanim odblokujesz ich następny zestaw. Wattson nie będzie dostępny, dopóki nie ukończysz zadania New Mauville. Wally można ponownie spotkać przy wyjściu z Victory Road; jego rewanż nie jest zgłaszany przez Match Call.', location: 'Hoenn / PokéNav / New Mauville', pokemon: ['Wally'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Ukończ ósmy Trick House puzzle', description: 'Wróć do Trick House po ukończeniu ligi i rozwiąż ósmy, ostatni zestaw zagadek. W pokoju Trick Mastera znajdziesz Nugget.', location: 'Route 110 — Trick House', items: ['Nugget'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Złap Ditto i odbierz drugą skamielinę', description: 'Po Hall of Fame odwiedź Fossil Maniac na Route 114. W jego domu pojawi się przejście do Desert Underpass, który prowadzi pod pustynią Route 111. W jaskini Ditto ma 50% spotkań (poziomy 38, 40–43 i 45), Whismur 34% (Lv.35–38), a Loudred 16% (Lv.38, 40 i 44). Na wschodnim końcu tunelu leży druga skamielina — Root Fossil albo Claw Fossil, zależnie od tego, którą zabrałeś wcześniej z Mirage Tower. Ditto jest szczególnie przydatny do hodowli, ponieważ może rozmnażać się z większością Pokémonów.', location: 'Route 114 / Desert Underpass', pokemon: ['Ditto', 'Whismur', 'Loudred'], encounterRatesPercent: {'Ditto': 50, 'Whismur': 34, 'Loudred': 16}, items: ['Root Fossil lub Claw Fossil'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Safari Zone — Area 1 (południowy wschód)', description: 'Podstawowy obszar Safari Zone. Procenty dotyczą spotkań w trawie; pozostałe metody, takie jak Surf i wędkarstwo, wymagają osobnych tabel.', location: 'Safari Zone — Area 1', pokemon: ['Oddish', 'Girafarig', 'Doduo', 'Natu', 'Wobbuffet', 'Pikachu', 'Gloom'], encounterRatesPercent: {'Oddish': 40, 'Girafarig': 20, 'Doduo': 10, 'Natu': 10, 'Wobbuffet': 10, 'Pikachu': 5, 'Gloom': 5}, optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Safari Zone — Area 2 (południowy zachód)', description: 'Drugi podstawowy obszar ma ten sam zestaw gatunków i takie same szanse spotkania w trawie jak Area 1.', location: 'Safari Zone — Area 2', pokemon: ['Oddish', 'Girafarig', 'Doduo', 'Natu', 'Wobbuffet', 'Pikachu', 'Gloom'], encounterRatesPercent: {'Oddish': 40, 'Girafarig': 20, 'Doduo': 10, 'Natu': 10, 'Wobbuffet': 10, 'Pikachu': 5, 'Gloom': 5}, optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Safari Zone — Area 3 (północny zachód)', description: 'W tym obszarze w trawie można spotkać Rhyhorna, Dodrio i Pinsira. Nie łącz tych procentów z innymi obszarami Safari Zone.', location: 'Safari Zone — Area 3', pokemon: ['Oddish', 'Rhyhorn', 'Gloom', 'Doduo', 'Dodrio', 'Pinsir'], encounterRatesPercent: {'Oddish': 30, 'Rhyhorn': 30, 'Gloom': 15, 'Doduo': 15, 'Dodrio': 5, 'Pinsir': 5}, optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Safari Zone — Area 4 (północny wschód)', description: 'Ten obszar ma osobną tabelę spotkań. Geodude pojawia się tu przez Rock Smash, a nie w zwykłej trawie.', location: 'Safari Zone — Area 4', pokemon: ['Oddish', 'Phanpy', 'Gloom', 'Natu', 'Xatu', 'Heracross', 'Geodude'], encounterRatesPercent: {'Oddish': 30, 'Phanpy': 30, 'Gloom': 15, 'Natu': 15, 'Xatu': 5, 'Heracross': 5}, optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Safari Zone — Area 5 (rozbudowa po National Dex)', description: 'Po otrzymaniu National Pokédexu ukończony zostaje południowo-wschodni obszar rozszerzenia. W trawie spotkasz dodatkowe gatunki z Johto.', location: 'Safari Zone — Area 5', pokemon: ['Mareep', 'Sunkern', 'Spinarak', 'Aipom', 'Hoothoot', 'Gligar', 'Snubbull', 'Stantler'], encounterRatesPercent: {'Mareep': 30, 'Sunkern': 30, 'Spinarak': 10, 'Aipom': 10, 'Hoothoot': 5, 'Gligar': 5, 'Snubbull': 5, 'Stantler': 5}, optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Safari Zone — Area 6 (rozbudowa po National Dex)', description: 'Północno-wschodni obszar rozszerzenia zawiera kolejne gatunki z Johto. Możesz tu także użyć Rock Smash, aby spotkać Shuckle.', location: 'Safari Zone — Area 6', pokemon: ['Aipom', 'Teddiursa', 'Ledyba', 'Sunkern', 'Hoothoot', 'Pineco', 'Houndour', 'Miltank', 'Shuckle'], encounterRatesPercent: {'Aipom': 30, 'Teddiursa': 30, 'Ledyba': 10, 'Sunkern': 10, 'Hoothoot': 5, 'Pineco': 5, 'Houndour': 5, 'Miltank': 5}, optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Ukończ Trainer Hill', description: 'Trainer Hill znajduje się na Route 111, na wschód od domu Winstrate. Wybierz jeden z czterech trybów: Normal, Variety, Unique lub Expert. Przejdź cztery piętra i walcz w Double Battles; nie otrzymujesz doświadczenia ani pieniędzy, a Pokémony nie są automatycznie leczone. Możesz używać przedmiotów z torby między walkami. Czas ukończenia decyduje o nagrodzie: poniżej 12 minut dostaniesz TM11 w Normal, TM19 w Variety, TM31 w Unique lub Elixir w Expert; wolniejsze czasy dają kolejno Ether, Max Potion, Revive, Fluffy Tail lub Great Ball. Na parterze po Hall of Fame sklep ma rozszerzony asortyment.', location: 'Route 111 — Trainer Hill', items: ['TM11 Sunny Day', 'TM19 Giga Drain', 'TM31 Brick Break', 'Elixir', 'Ether', 'Max Potion', 'Revive', 'Fluffy Tail', 'Great Ball'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Zdobądź codzienne jagody od Berry Mastera i jego żony', description: 'Na Route 123 Berry Master daje codziennie dwie losowe jagody z puli Pomeg, Kelpsy, Qualot, Hondew, Grepa, Tamato, Cornn, Magost, Rabuta i Nomel. Jego żona również daje jedną jagodę dziennie. W Emerald specjalne hasło GREAT BATTLE daje Spelon Berry; po poznaniu wszystkich pięciu haseł jej codzienny prezent wraca do puli dziesięciu zwykłych jagód. W ogrodzie zbierz też po osiem Grepa, Pomeg i Qualot Berries. Nie używaj list haseł z Ruby/Sapphire — nie są poprawne dla Emerald.', location: 'Route 123 — Berry Master’s House', items: ['Grepa Berry ×8', 'Pomeg Berry ×8', 'Qualot Berry ×8', 'Spelon Berry'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Ukończ Abandoned Ship i New Mauville', description: 'Abandoned Ship leży na Route 108. Najpierw zbierz Storage Key w południowo-zachodnim rogu gabinetu kapitana i otwórz zamknięty schowek na B1F, aby zdobyć TM13 Ice Beam. Po uzyskaniu Dive wróć do ukrytego piętra: Rm. 2 Key znajduje się w Room 5 i otwiera Room 2 ze Scannerem. Dodatkowa odnoga prowadzi przez Room 3 (Water Stone i Rm. 1 Key), Room 1 (TM18 Rain Dance i Rm. 4 Key), Room 4 (Rm. 6 Key) oraz Room 6 (Luxury Ball). Zanieś Scanner Captain Sternowi w Slateport i wybierz DeepSeaTooth albo DeepSeaScale — otrzymasz tylko jeden z nich. New Mauville odblokowuje Wattson po zdobyciu Balance Badge: weź Basement Key, użyj Surf pod północnym końcem Cycling Road na Route 110, przełączaj niebieskie i zielone drzwi, wyłącz czerwonym przyciskiem generator i zabierz Thunderstone. Uważaj na trzy Voltorby udające przedmioty. Wróć do Wattsona po TM24 Thunderbolt.', location: 'Route 108 — Abandoned Ship / Route 110 — New Mauville / Slateport City', pokemon: ['Tentacool', 'Tentacruel', 'Magnemite', 'Voltorb', 'Magneton', 'Electrode'], items: ['Storage Key', 'TM13 Ice Beam', 'Rm. 1 Key', 'Rm. 2 Key', 'Rm. 4 Key', 'Rm. 6 Key', 'Water Stone', 'TM18 Rain Dance', 'Luxury Ball', 'Scanner', 'DeepSeaTooth lub DeepSeaScale', 'Basement Key', 'Thunderstone', 'TM24 Thunderbolt'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Zdobądź wszystkie wstążki z Pokémon Contests', description: 'Wystartuj w pięciu kategoriach konkursów: Cool, Beauty, Cute, Smart i Tough. Każda ma cztery rangi, a zdobycie Master Rank i wygranie konkursów pozwala uzyskać wstążki oraz obrazy w Lilycove Museum.', location: 'Lilycove City — Contest Hall / Lilycove Museum', optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Zbadaj Altering Cave i inne lokacje poboczne', description: 'Po Hall of Fame wejdź do Altering Cave na Route 103 — w standardowym Pokémon Emerald występuje tam wyłącznie Zubat na poziomach 6, 8, 10, 12, 14 i 16. Rzadkie gatunki z Johto, o których wspominają plotki, nie są dostępne w zwykłej wersji gry bez specjalnych modyfikacji lub innych danych eventowych. Wróć też do Shoal Cave przy obu stanach pływu, sprawdź Scorched Slab, Artisan Cave, Trainer Hill i Desert Underpass. Zapisuj przedmioty ukryte osobno od tych leżących na ziemi, aby nie pominąć niczego przy kompletowaniu 100%.', location: 'Route 103 / Hoenn', pokemon: ['Zubat', 'Smeargle'], encounterRatesPercent: {'Zubat': 100}, optional: true),
  GuideStep(section: 'Legendarne Pokémony', title: 'Złap Kyogre w Marine Cave', description: 'W Weather Institute meteorolog na 2F wskaże intensywne ulewy na Route 105, 125, 127 lub 129. Marine Cave pojawia się na wskazanej trasie i wymaga Surf oraz Dive — szukaj małego ciemnego pola głębokiej wody, zanurkuj, a następnie wynurz się wewnątrz jaskini. W drugiej komorze czeka Kyogre Lv.70 z Drizzle i ruchami Hydro Pump, Rest, Sheer Cold oraz Double-Edge. Zapisz grę przed spotkaniem. Jeśli Kyogre zostanie pokonany, jaskinia zniknie i później pojawi się w innym miejscu; po złapaniu możesz zająć się Groudonem.', location: 'Weather Institute / Marine Cave', pokemon: ['Kyogre'], optional: true),
  GuideStep(section: 'Legendarne Pokémony', title: 'Zdobądź drugiego Eon Pokémona na Southern Island', description: 'Drugi z pary Latias/Latios nie wędruje po Hoenn. Można go spotkać na Southern Island po uzyskaniu Eon Ticket, który w oryginalnym Emerald był dystrybuowany przez e-Reader lub mieszanie rekordów z graczem posiadającym bilet. Norman przekazuje bilet i kieruje cię do Lilycove, skąd Mr. Briney zabiera cię na wyspę. W lesie spotkasz drugiego Eon Pokémona na poziomie 50; trzyma Soul Dew i zna ruchy charakterystyczne dla swojego gatunku, Psychic oraz Recover. W zwykłej współczesnej rozgrywce bez zachowanego eventowego biletu ta lokacja może być niedostępna.', location: 'Southern Island', pokemon: ['Latias', 'Latios'], items: ['Eon Ticket', 'Soul Dew'], optional: true),
  GuideStep(section: 'Legendarne Pokémony', title: 'Sprawdź eventowe wyspy i wymagane bilety', description: 'Faraway Island (Mew), Birth Island (Deoxys) i Navel Rock (Lugia oraz Ho-Oh) wymagają odpowiednich specjalnych biletów Nintendo-event: Old Sea Map, AuroraTicket i MysticTicket. Nie są to przedmioty, które można normalnie zdobyć podczas standardowej fabuły Emerald. Jeśli grasz na oryginalnym kartridżu bez zachowanych dystrybucji, potraktuj te spotkania jako zawartość eventową, a nie obowiązkowy warunek regionalnego Pokédexu. Po zdobyciu właściwego biletu odwiedź port w Lilycove i wybierz podróż na wskazaną wyspę.', location: 'Faraway Island / Birth Island / Navel Rock', pokemon: ['Mew', 'Deoxys', 'Lugia', 'Ho-Oh'], items: ['Old Sea Map', 'AuroraTicket', 'MysticTicket'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Złap Feebasa na Route 119', description: 'Feebas nie ma stałej trawy ani stałego miejsca na rzece. Gra losuje sześć z 444 możliwych pól wody na Route 119; tylko na tych polach może pojawić się Feebas, a jego szansa w spotkaniu wynosi 50%. Możesz użyć dowolnej wędki, także Old Rod. Ważne: sprawdzane jest pole wody, na które zarzucasz wędkę, a nie pole, na którym stoisz. Zarzuć wędkę przynajmniej raz na każdym dostępnym polu i przesuwaj się systematycznie wzdłuż rzeki. Jeśli zmienisz Trendy Phrase w Dewford Town, sześć pól zostanie wylosowanych ponownie. Gdy złapiesz Feebasa, podnieś jego Beauty Pokéblockami i ewoluuj go w Milotica przez awans na poziom po osiągnięciu odpowiednio wysokiej Beauty.', location: 'Route 119 — rzeka', pokemon: ['Feebas', 'Milotic'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Safari Zone — łowienie i Surf w rozszerzeniu', description: 'Po zdobyciu National Pokédexu odwiedź dwa nowe wschodnie obszary Safari Zone. W południowo-wschodnim Area 5 Surf daje Wooper 60%, Marill 39% i Quagsire 1%. Old Rod: Magikarp 70%, Goldeen 30%; Good Rod: Magikarp 60%, Goldeen 20%, Remoraid 20%; Super Rod: Goldeen 40%, Remoraid 59%, Octillery 1%. Zabierz Super Rod i Surf, jeśli chcesz zebrać wszystkie gatunki z wody. Pamiętaj, że Safari Game ma limit 500 kroków i 30 Safari Balls.', location: 'Safari Zone — Area 5 (południowo-wschodnie rozszerzenie)', pokemon: ['Wooper', 'Marill', 'Quagsire', 'Magikarp', 'Goldeen', 'Remoraid', 'Octillery'], encounterRatesPercent: {'Wooper': 60, 'Marill': 39, 'Quagsire': 1}, items: ['Safari Balls ×30'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Safari Zone — złap Shuckle przez Rock Smash', description: 'W północno-wschodnim Area 6 po rozszerzeniu Safari Zone rozbijaj skały ruchem Rock Smash. Shuckle jest jedynym Pokémonem spotykanym w ten sposób w tym obszarze; szansa spotkania wynosi 100%. W trawie nadal występują Aipom, Teddiursa, Ledyba, Sunkern, Hoothoot, Pineco, Houndour i Miltank. To osobna metoda spotkania, więc nie mieszaj jej z procentami tabeli trawiastej.', location: 'Safari Zone — Area 6 (północno-wschodnie rozszerzenie)', pokemon: ['Shuckle'], encounterRatesPercent: {'Shuckle': 100}, optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Ukończ Shoal Cave przy obu stanach pływu', description: 'Pływy zmieniają się co sześć godzin czasu gry: o 3:00, 9:00, 15:00 i 21:00. Niski pływ trwa od 3:00 do 8:59 oraz od 15:00 do 20:59; wysoki od 9:00 do 14:59 oraz od 21:00 do 2:59. Przy wysokim pływie użyj Surf, aby dostać się do Second Cavern: zbierz cztery Shoal Shells, Rare Candy na wschód od środkowej drabiny i Big Pearl na północno-wschodniej półce wejścia. Przy niskim pływie przejdź przez Second, Fourth i Third Cavern do Ice Cavern. Zbierz cztery Shoal Salts, Ice Heal w Fourth Cavern, Focus Band od Black Belta w Third Cavern, NeverMeltIce na południowym końcu centralnej platformy i TM07 Hail na górnej półce. W Third Cavern użyj Strength do przesunięcia głazu. Starzec przy wejściu wymieni komplet czterech Shoal Shells i czterech Shoal Salts na Shell Bell; surowce odnawiają się każdego dnia. W głównej jaskini spotkasz Spheala 50%, Zubata 45% i Golbata 5%. W Ice Cavern spotkania są inne: Spheal 45%, Zubat 40%, Snorunt 10%, Golbat 5%.', location: 'Shoal Cave — high tide / low tide', pokemon: ['Spheal', 'Zubat', 'Golbat', 'Snorunt'], encounterRatesPercent: {'Spheal': 50, 'Zubat': 45, 'Golbat': 5}, items: ['Shoal Shell ×4', 'Shoal Salt ×4', 'Rare Candy', 'Big Pearl', 'Ice Heal', 'Focus Band', 'NeverMeltIce', 'TM07 Hail', 'Shell Bell'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Safari Zone — Surf i wędki w Area 2', description: 'W południowo-zachodnim Area 2 możesz używać Surf i wszystkich trzech wędek. Surf: Psyduck 100%. Old Rod: Magikarp 70%, Goldeen 30%. Good Rod: Magikarp 60%, Goldeen 40%. Super Rod: Goldeen 80%, Seaking 20%. Tabele wodne są oddzielne od spotkań w trawie, dlatego nie sumuj ich z tabelą lądową.', location: 'Safari Zone — Area 2 (południowy zachód)', pokemon: ['Psyduck'], encounterRatesPercent: {'Psyduck': 100}, optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Safari Zone — Surf i wędki w Area 3', description: 'W północno-zachodnim Area 3 spotkasz Psyducka 95% i Golducka 5% podczas Surf. Old Rod: Magikarp 70%, Goldeen 30%. Good Rod: Magikarp 60%, Goldeen 40%. Super Rod: Goldeen 80%, Seaking 20%. Nie pomyl tej strefy z Area 2 — tabele trawiaste są inne, a spotkania wodne również mają osobne wartości.', location: 'Safari Zone — Area 3 (północny zachód)', pokemon: ['Psyduck', 'Golduck'], encounterRatesPercent: {'Psyduck': 95, 'Golduck': 5}, optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Uzupełnij spotkania wodne w Shoal Cave', description: 'Podczas Surf w Shoal Cave spotkasz Tentacool 60%, Zubat 30% i Spheala 10%. Old Rod: Magikarp 70%, Tentacool 30%. Good Rod: Magikarp 60%, Tentacool 20%, Wailmer 20%. Super Rod: Wailmer 100%. Te tabele dotyczą wody i wędkowania, a nie spotkań w jaskini na lądzie; sprawdź je niezależnie od pływu, aby uzupełnić wszystkie gatunki.', location: 'Shoal Cave — Surf / Fishing', pokemon: ['Tentacool', 'Zubat', 'Spheal'], encounterRatesPercent: {'Tentacool': 60, 'Zubat': 30, 'Spheal': 10}, optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Złap Snorunta w lodowej komnacie Shoal Cave', description: 'Snorunt występuje wyłącznie w Ice Cavern podczas niskiego pływu. Tabela spotkań w tej komnacie: Spheal 45%, Zubat 40%, Snorunt 10%, Golbat 5%. Snorunt pojawia się na poziomach 26, 28 lub 30. To jedyne miejsce w standardowym Emerald, gdzie można złapać go na wolności. Wykorzystaj lodowe pola, aby dotrzeć do NeverMeltIce i TM07 Hail.', location: 'Shoal Cave — Ice Cavern (low tide)', pokemon: ['Spheal', 'Zubat', 'Snorunt', 'Golbat'], encounterRatesPercent: {'Spheal': 45, 'Zubat': 40, 'Snorunt': 10, 'Golbat': 5}, items: ['TM07 Hail', 'NeverMeltIce'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Uzupełnij Trick House — ósma zagadka', description: 'Po wejściu do Hall of Fame wróć do Trick House na Route 110. Ostatnia, ósma zagadka odblokowuje się po ukończeniu poprzednich siedmiu. Przeszukaj pomieszczenia, pokonaj trenerów i dotrzyj do Trick Mastera. W nagrodę otrzymasz Nugget. To ostatni standardowy etap domu zagadek w Emerald.', location: 'Route 110 — Trick House', items: ['Nugget'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Odbierz startera Johto za pełny Hoenn Pokédex', description: 'Po zdobyciu National Pokédexu złap lub wyewoluuj wszystkie 200 Pokémonów z regionalnego Hoenn Pokédexu. Wróć do laboratorium Profesora Bircha w Littleroot Town. Po sprawdzeniu kompletnego Hoenn Dexu profesor pozwoli wybrać jednego startera z Johto: Chikorita, Cyndaquil albo Totodile. Wybór jest jednorazowy w danym zapisie, więc jeśli chcesz mieć całą trójkę, potrzebujesz wymian lub kolejnych zapisów.', location: 'Littleroot Town — Professor Birch’s Lab', pokemon: ['Chikorita', 'Cyndaquil', 'Totodile'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Zbierz przedmioty w Safari Zone', description: 'Przy okazji łapania Pokémonów sprawdź również wszystkie przedmioty. Area 2: Max Revive na południowym brzegu stawu (wymaga Surf). Area 3: TM22 SolarBeam przy północno-wschodnim brzegu stawu (wymaga Mach Bike i Surf). Area 4: Calcium na północnym skraju północno-zachodniej kępy trawy (Acro Bike). Rozszerzone Area 5: ukryty PP Up na południe od najbardziej wysuniętego na południe stoiska Pokéblocków, ukryty Full Restore na północnym skraju południowo-wschodniej kępy trawy oraz Big Pearl na północno-wschodniej kępie trawy, na wschód od wodospadu (Surf). Rozszerzone Area 6: ukryty Rare Candy w południowo-wschodniej części, ukryty Zinc w pierwszej wnęce skalnej ścieżki i Nugget między dwiema półkami na końcu tej ścieżki.', location: 'Safari Zone — Areas 2–6', items: ['Max Revive', 'TM22 SolarBeam', 'Calcium', 'PP Up (ukryty)', 'Full Restore (ukryty)', 'Big Pearl', 'Rare Candy (ukryty)', 'Zinc (ukryty)', 'Nugget'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Złap Pokémony podwodne na Route 124 i przy Abandoned Ship', description: 'Po zdobyciu Dive przeszukuj ciemne pola podwodne z trawą morską. We wszystkich takich obszarach spotkania są takie same: Clamperl 65%, Chinchou 30% i Relicanth 5% (poziomy odpowiednio 20–35, 20–30 i 30–35). Najłatwiej szukać ich na Route 124, ale możesz też eksplorować podwodne obszary w pobliżu Abandoned Ship. Na Route 124 wynurzaj się w kilku różnych miejscach i sprawdzaj także ukryte przedmioty w prześwitach trawy: Green Shard, Carbos, dwa Heart Scale, Calcium, Big Pearl i Pearl. Trzy kolorowe odłamki na powierzchni — Blue, Red i Yellow Shard — są w płytkich zatoczkach po wynurzeniu w odpowiednich Dive spotach.', location: 'Route 124 / Abandoned Ship — underwater', pokemon: ['Clamperl', 'Chinchou', 'Relicanth'], encounterRatesPercent: {'Clamperl': 65, 'Chinchou': 30, 'Relicanth': 5}, items: ['Green Shard (ukryty)', 'Carbos (ukryty)', 'Heart Scale ×2 (ukryte)', 'Calcium (ukryty)', 'Big Pearl (ukryty)', 'Pearl (ukryty)', 'Blue Shard', 'Red Shard', 'Yellow Shard'], optional: true),

  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Abandoned Ship — spotkania podczas Surf', description: 'Na zalanych częściach Abandoned Ship użyj Surf. Tentacool pojawia się z szansą 99%, a Tentacruel 1%. Obie podwodne sekcje statku korzystają z tej samej tabeli spotkań.', location: 'Route 108 — Abandoned Ship (Surf)', pokemon: ['Tentacool', 'Tentacruel'], encounterRatesPercent: {'Tentacool': 99, 'Tentacruel': 1}, optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Abandoned Ship — Old Rod', description: 'Przy użyciu Old Rod możesz złowić Magikarpa (70%) lub Tentacoola (30%). Pokémony pojawiają się na poziomach 5–10.', location: 'Route 108 — Abandoned Ship (Old Rod)', pokemon: ['Magikarp', 'Tentacool'], encounterRatesPercent: {'Magikarp': 70, 'Tentacool': 30}, optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Abandoned Ship — Good Rod', description: 'Good Rod pozwala złowić Magikarpa z szansą 60% oraz Tentacoola z szansą 40%. Poziomy spotkań to 10–30.', location: 'Route 108 — Abandoned Ship (Good Rod)', pokemon: ['Magikarp', 'Tentacool'], encounterRatesPercent: {'Magikarp': 60, 'Tentacool': 40}, optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Abandoned Ship — Super Rod', description: 'Super Rod daje 80% szansy na Tentacoola i 20% na Tentacruela. Spotkania występują na poziomach 20–35.', location: 'Route 108 — Abandoned Ship (Super Rod)', pokemon: ['Tentacool', 'Tentacruel'], encounterRatesPercent: {'Tentacool': 80, 'Tentacruel': 20}, optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Przeszukaj podwodne piętro Abandoned Ship', description: 'Po zdobyciu Dive wróć na statek i zanurkuj do zalanych pomieszczeń. Otwieraj kolejne kabiny za pomocą kluczy: znajdziesz m.in. Water Stone, TM18 Rain Dance, TM13 Ice Beam, Luxury Ball, Dive Ball i Scanner. Zbierz ukryte klucze w pokojach, aby dostać się do wszystkich sześciu kabin. Scanner oddaj Captainowi Sternowi w Slateport — wybierzesz w zamian DeepSeaTooth albo DeepSeaScale.', location: 'Route 108 — Abandoned Ship (B1F / Dive)', items: ['Water Stone', 'TM18 Rain Dance', 'TM13 Ice Beam', 'Luxury Ball', 'Dive Ball', 'Scanner', 'Room 1 Key', 'Room 2 Key', 'Room 4 Key', 'Room 6 Key'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Sprawdzaj codzienne wydarzenia i Mirage Island', description: 'Wróć regularnie do miejsc z codziennymi prezentami: Berry Master na Route 123 daje dwie jagody, jego żona jedną; jagody rozdają też postacie w Pretty Petal Flower Shop na Route 104, przy postoju na Route 111, przed domem Lanette na Route 114, na Route 120, w północno-zachodnim Lilycove i Kiri w Sootopolis. Co tydzień brat przewodniczącego Pokémon Fan Club w Pacifidlog daje TM27 Return albo TM21 Frustration. Sprawdzaj telewizję: mogą pojawić się roje Pokémonów, promocje Game Corner, Blend Master w Contest Hall, wyprzedaż na dachu Department Store i tańsze witaminy w Slateport. W Pacifidlog rozmawiaj codziennie ze starcem obserwującym Mirage Island. Wyspa pojawia się na Route 130 tylko na dany dzień, jeśli ukryta wartość jednego z Pokémonów w drużynie pasuje do dziennego losowania; w trawie spotkasz tam wyłącznie Wynauta (Lv.5–50, 100%), a na wyspie rośnie jedyna Liechi Berry w grze.', location: 'Hoenn — daily events / Route 130', pokemon: ['Wynaut'], encounterRatesPercent: {'Wynaut': 100}, items: ['TM27 Return', 'TM21 Frustration', 'Liechi Berry'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Dokończ Secret Base, hodowlę i kolekcję dekoracji', description: 'Użyj Secret Power (TM43), aby utworzyć własną Secret Base w odpowiednim miejscu na skałach, drzewach lub krzakach. Możesz mieć aktywną tylko jedną bazę, ale po przeprowadzce dekoracje trafiają do PC; wnętrze pozwala ustawić maksymalnie 16 dekoracji. Zdobywaj meble i lalki w sklepie w Fortree, Lilycove Department Store, Mauville Game Corner oraz jako nagrody za Contests i Battle Frontier. Odwiedź także Day Care na Route 117: zostaw parę kompatybilnych Pokémonów (wspólna Egg Group i przeciwne płcie) albo Pokémona z Ditto, odbierz jajko od opiekuna i wykluj je, chodząc. Hodowla pozwala uzupełnić wcześniejsze stadia ewolucji, uzyskać wybrane ruchy jajeczne i przygotować Pokémony do Battle Frontier; część niemowlęcych gatunków wymaga odpowiedniego kadzidła trzymanego przez rodzica.', location: 'Hoenn — Secret Bases / Route 117 Day Care', items: ['TM43 Secret Power', 'Decorations', 'Eggs', 'Sea Incense', 'Lax Incense'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Zamknij kolekcję konkursów i wstążek', description: 'W Lilycove Contest Hall zalicz pięć kategorii: Cool, Beauty, Cute, Smart i Tough, każdą na rangach Normal, Super, Hyper i Master. Zwycięstwa na rangach dają odpowiednie Contest Ribbons; wygrana Master Rank pozwala zdobyć obraz w Lilycove Museum, jeśli spełnisz warunki konkursu i przygotujesz odpowiednio mocne Pokéblocki. Łącz jagody w Berry Blenderze z NPC lub innymi graczami, aby tworzyć Pokéblocki podnoszące pięć cech konkursowych. Uzupełnij też pozostałe wstążki zdobywane za Ligę, wysiłek, przyjaźń, rozwój i Battle Tower — nie wszystkie pochodzą z Contest Hall. Sprawdź Ribbon Case, aby odróżnić zdobyte wstążki od tych, których jeszcze brakuje.', location: 'Lilycove City — Contest Hall / Museum', items: ['Contest Ribbons', 'Pokéblocks'], optional: true),
  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Poznaj granice Pokédexu w jednej kopii Emerald', description: 'Pełne 200 wpisów Hoenn Pokédexu wymaga zarejestrowania Pokémonów jako złapanych, a nie tylko widzianych. W jednej kopii Emerald nie uzyskasz wszystkich wpisów bez wymian: potrzebujesz pozostałych dwóch starterów Hoenn, ewolucji przez wymianę (Alakazam, Machamp, Golem, Politoed, Kingdra, Huntail i Gorebyss) oraz gatunków niedostępnych w zwykłych spotkaniach Emerald, m.in. Surskit, Meditite, Roselia, Zangoose i Lunatone; część można zdobyć tylko przez kompatybilne wymiany lub specjalne mieszanie rekordów. Po 200 wpisach Birch daje wybór jednego startera Johto. National Dex i dyplom National Pokédex mają osobne wymagania — dyplom Emerald obejmuje 380 gatunków. Nie traktuj historycznych Pokémonów eventowych (np. Mew, Celebi, Jirachi i Deoxys) jako normalnych spotkań możliwych do zdobycia na standardowym kartridżu; pełna kolekcja 386 wymaga zewnętrznych źródeł, wymian lub dystrybucji eventowych.', location: 'Littleroot Town — Professor Birch / Lilycove — Game Designer', pokemon: ['Alakazam', 'Machamp', 'Golem', 'Politoed', 'Kingdra', 'Huntail', 'Gorebyss', 'Surskit', 'Meditite', 'Roselia', 'Zangoose', 'Lunatone', 'Chikorita', 'Cyndaquil', 'Totodile'], optional: true),

