  GuideStep(section: 'Zadania poboczne i Pokédex', title: 'Safari Zone Area 2 — Good Rod', description: 'W Area 2 użyj Good Rod. Magikarp ma 60% szansy, a Goldeen 40%.', location: 'Safari Zone — Area 2 (Good Rod)', pokemon: ['Magikarp', 'Goldeen'], encounterRatesPercent: {'Magikarp': 60, 'Goldeen': 40}, optional: true),
